html,body{overflow-x:clip;max-width:100%}
/* Layout: a stationer's catalogue. Paper ground, ink type, one oxblood accent; app screens sit on the same paper. Deliberately single-theme (printed-paper look) on any host. */
:root{
  color-scheme:light;
  --bg:#f3eee5; --surface:#fbf8f2; --sunk:#ebe4d8; --fg:#221b17; --muted:#6f645a; --line:rgba(34,27,23,.16);
  --accent:#6e1a26; --accent-ink:#fbf6ee; --accent-soft:#efdcd8; --brass:#9a7a45; --danger:#a3261e; --ok:#2f6b45;
  --dark:#211a17; --dark-fg:#efe7da;
  --f-display:"Cormorant Garamond", "Iowan Old Style", Georgia, serif; --f-body:"Jost", "Futura", "Avenir Next", system-ui, sans-serif;
  --r:2px; --shadow:0 1px 2px rgba(34,27,23,.08),0 14px 34px rgba(34,27,23,.10);
}
*{box-sizing:border-box}
html,body{background:var(--bg);color:var(--fg)}
body{font-family:var(--f-body);font-size:15px;line-height:1.6;-webkit-font-smoothing:antialiased;position:relative}
body::before{content:"";position:fixed;inset:0;background:url(/assets/paper.jpg) 0 0/360px;mix-blend-mode:multiply;opacity:.7;pointer-events:none;z-index:0}
body > *{position:relative;z-index:1}
h1,h2,h3{font-family:var(--f-display);font-weight:400;line-height:1.05;text-wrap:balance;margin:0;letter-spacing:-.005em}
p{margin:0}
a{color:inherit}
button,input,select,textarea{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.wrap{max-width:1200px;margin:0 auto;padding-left:max(16px, env(safe-area-inset-left, 0px));padding-right:max(16px, env(safe-area-inset-right, 0px))}
.eyebrow{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--accent);font-weight:500}
.muted{color:var(--muted)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid transparent;border-radius:var(--r);padding:12px 22px;font-weight:500;cursor:pointer;text-decoration:none;font-size:12px;letter-spacing:.14em;text-transform:uppercase;transition:background .15s,color .15s}
.btn-primary{background:var(--accent);color:var(--accent-ink)}
.btn-primary:hover{background:#561420}
.btn-ghost{background:transparent;border-color:var(--fg);color:var(--fg)}
.btn-ghost:hover{background:var(--fg);color:var(--bg)}
.btn-ghost-light{background:transparent;border:1px solid rgba(239,231,218,.5);color:var(--dark-fg)}
.btn-ghost-light:hover{background:var(--dark-fg);color:var(--dark)}
.btn-link{background:none;padding:12px 2px;color:var(--fg);text-transform:none;letter-spacing:0;font-size:15px;border-bottom:1px solid var(--fg);border-radius:0}
.btn-sm{padding:8px 14px;font-size:11px}
.btn-danger{color:var(--danger);border-color:var(--line);background:transparent}
.btn[disabled]{opacity:.45;cursor:not-allowed}
.chip{display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border-radius:999px;border:1px solid var(--line);background:transparent;cursor:pointer;font-size:13px}
.chip[aria-pressed="true"]{background:var(--fg);color:var(--bg);border-color:var(--fg)}
.tag{display:inline-block;font-size:10px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;padding:2px 8px;border:1px solid currentColor;color:var(--accent);border-radius:2px}
.tag.brass{color:var(--brass)}

/* header: a centred masthead */
.site-head{position:sticky;top:env(safe-area-inset-top, 0px);z-index:40;background:color-mix(in srgb, var(--bg) 92%, transparent);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.site-head .wrap{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;height:68px}
.brand{display:flex;flex-direction:column;align-items:center;text-decoration:none;line-height:1}
.brand .wm{font-family:var(--f-display);font-size:30px;font-weight:500;font-style:italic;letter-spacing:.01em}
.brand .tag-line{font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:var(--muted);margin-top:4px}
.nav{display:flex;gap:4px;align-items:center}
.nav-r{justify-content:flex-end}
.nav a:not(.btn){padding:8px 10px;text-decoration:none;font-size:13px;letter-spacing:.06em;color:var(--muted)}
.nav a:not(.btn):hover,.nav a[aria-current="page"]:not(.btn){color:var(--fg)}
.nav a[aria-current="page"]:not(.btn){text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:1px}
@media (max-width:720px){.nav a.hide-sm{display:none}.brand .tag-line{display:none}.brand .wm{font-size:24px}.nav a:not(.btn){padding:6px 4px;font-size:12px}.site-head .btn-sm{padding:7px 8px;letter-spacing:.04em;font-size:10px}}

.view{display:none}
.view.on{display:block}

/* hero with a flat-lay of real cards */
