/* no visible scrollbars inside the phone preview or on the step tabs (still scrollable) */
.inv .scroller,.phone .screen,.phone .screen *,.tabs,#ed-tabs,.ed-tabs{scrollbar-width:none;-ms-overflow-style:none}
.inv .scroller::-webkit-scrollbar,.phone .screen::-webkit-scrollbar,.phone .screen *::-webkit-scrollbar,.tabs::-webkit-scrollbar,#ed-tabs::-webkit-scrollbar,.ed-tabs::-webkit-scrollbar{display:none;width:0;height:0}
.jawi-tools{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.jawi-kb{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));min-width:0;max-width:100%;gap:4px;margin-top:8px;padding:8px;border:1px solid var(--line);background:var(--surface);direction:rtl}
.jawi-kb[hidden]{display:none}.jawi-kb .jawi-digits{grid-column:1/-1;display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:4px;padding-bottom:6px;margin-bottom:2px;border-bottom:1px dashed var(--line)}
.jawi-kb button{font-family:"Amiri",serif;font-size:20px;line-height:1;padding:8px 0;border:1px solid var(--line);background:var(--bg);cursor:pointer;border-radius:4px}
