.scan-box{display:flex;flex-direction:column;gap:10px;align-items:center;padding:14px;border:1px solid var(--line);background:var(--surface);margin-bottom:12px}
.scan-box video{width:100%;max-width:340px;aspect-ratio:1;object-fit:cover;background:#000}
.pill.in{background:color-mix(in srgb,var(--ok) 18%,transparent);color:var(--ok)}
.pkg-bar{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;padding:18px 20px;background:var(--surface);border:1px solid var(--line)}
.pkg-bar b{font-family:var(--f-display);font-size:28px;font-weight:400;font-style:italic}
.foot-nav{display:flex;justify-content:space-between;gap:12px;margin-top:8px}
.mobile-preview{position:fixed;right:max(16px, env(safe-area-inset-right, 0px));bottom:calc(16px + env(safe-area-inset-bottom, 0px));z-index:30;display:none;box-shadow:var(--shadow)}
@media (max-width:940px){.mobile-preview.on{display:inline-flex}}
.summary{border-top:1px solid var(--line)}
.summary dl{display:grid;grid-template-columns:140px 1fr;margin:0}
.summary dt,.summary dd{padding:11px 0;border-bottom:1px solid var(--line);margin:0;min-width:0;overflow-wrap:anywhere}
.summary dt{color:var(--muted);font-size:11px;letter-spacing:.1em;text-transform:uppercase}
.summary dd{font-family:var(--f-display);font-size:19px}

/* checkout */
.checkout{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:40px;padding-block:28px 80px;align-items:start}
@media (max-width:900px){.checkout{grid-template-columns:1fr}}
.card{background:var(--surface);border:1px solid var(--line);padding:24px;display:flex;flex-direction:column;gap:16px}
.card h3{font-family:var(--f-display)!important;font-size:24px!important;font-weight:400!important;font-style:italic}
.pay-methods{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.pay-methods button,.banks button{border:1px solid var(--line);background:transparent;padding:12px 8px;cursor:pointer;font-size:13px}
.pay-methods button[aria-pressed="true"],.banks button[aria-pressed="true"]{border-color:var(--fg);background:var(--fg);color:var(--bg)}
.banks{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
@media (max-width:480px){.banks,.pay-methods{grid-template-columns:repeat(2,1fr)}}
.line-items{display:flex;flex-direction:column;gap:10px;font-size:14px}
.line-items div{display:flex;justify-content:space-between;gap:10px;font-variant-numeric:tabular-nums}
.line-items .total{border-top:1px solid var(--line);padding-top:12px;font-family:var(--f-display);font-size:24px}
.slug-input{display:flex;align-items:center;border:1px solid var(--line);background:var(--surface)}
.slug-input span{padding:11px 0 11px 12px;color:var(--muted);white-space:nowrap}
.slug-input input{border:0;padding-left:2px;background:transparent}
.slug-input input:focus{outline:none}
.slug-input:focus-within{outline:1px solid var(--fg)}
.ok-msg{color:var(--ok);font-size:13px}.err-msg{color:var(--danger);font-size:13px}
.demo-note{font-size:13px;padding:12px 14px;background:var(--sunk);color:var(--fg)}
.processing{display:flex;flex-direction:column;align-items:center;gap:14px;padding:30px;text-align:center}
.spinner{width:34px;height:34px;border-radius:50%;border:2px solid var(--line);border-top-color:var(--accent);animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.success{text-align:center;padding-block:64px;display:flex;flex-direction:column;align-items:center;gap:18px}
.success h1{font-weight:300}
.success .seal{width:96px;height:96px;background:url(/assets/seal-merah.webp) center/contain no-repeat;filter:drop-shadow(0 4px 6px rgba(0,0,0,.25))}
.linkbox{display:flex;gap:8px;align-items:center;padding:8px 8px 8px 16px;border:1px solid var(--line);background:var(--surface);max-width:100%}
.linkbox code{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}

/* dashboard */
.dash{display:grid;grid-template-columns:300px minmax(0,1fr);gap:36px;padding-block:28px 80px;align-items:start}
@media (max-width:900px){.dash{grid-template-columns:1fr}}
.order-list{display:flex;flex-direction:column;gap:10px}
.order-item{display:flex;gap:12px;align-items:center;padding:12px;border:1px solid var(--line);background:var(--surface);cursor:pointer;text-align:left;width:100%}
.order-item[aria-current="true"]{border-color:var(--fg)}
.order-item .sw{width:40px;height:54px;flex:0 0 40px}
.order-item .t{min-width:0;flex:1}
.order-item .t b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-family:var(--f-display);font-size:19px;font-weight:500}
.order-item .t span{font-size:12px;color:var(--muted)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-left:1px solid var(--line)}
.kpi{padding:16px 18px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--surface)}
.kpi b{display:block;font-family:var(--f-display);font-size:40px;font-weight:400;font-variant-numeric:tabular-nums;line-height:1.05}
.kpi span{font-size:12px;color:var(--muted)}
@media (max-width:640px){.kpis{grid-template-columns:repeat(2,1fr)}}
.meter{height:6px;background:var(--sunk);overflow:hidden;display:flex}
.meter i{display:block;height:100%}
.tbl-wrap{overflow-x:auto;border:1px solid var(--line);background:var(--surface)}
table{border-collapse:collapse;width:100%;font-size:14px}
th,td{padding:11px 14px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
th{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);font-weight:500}
tr:last-child td{border-bottom:0}
.pill{display:inline-block;padding:1px 10px;font-size:12px;border:1px solid currentColor}
.pill.yes{color:var(--ok)}
.pill.no{color:var(--danger)}
.empty{border:1px dashed var(--muted);padding:44px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:12px}
.empty h2{font-style:italic}
.wish-admin{display:flex;flex-direction:column}
.wish-admin .w{display:flex;gap:12px;justify-content:space-between;align-items:start;padding:14px 0;border-top:1px solid var(--line)}
.wish-admin .w.hidden-w{opacity:.5}
.confirm-bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:12px 14px;background:var(--accent-soft)}
.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom, 0px));transform:translateX(-50%) translateY(20px);background:var(--fg);color:var(--bg);padding:11px 20px;font-size:14px;opacity:0;transition:.25s;z-index:200;pointer-events:none;max-width:calc(100% - 32px)}
.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
.conn{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px}
.conn i{width:7px;height:7px;border-radius:50%;background:var(--brass)}
.conn.live i{background:var(--ok)}

#inv-root{z-index:100}
.inv-overlay{position:fixed;inset:0;z-index:100;background:#141110;display:flex;justify-content:center}
.inv-overlay .inv-host{width:100%;max-width:480px;height:100%;position:relative}
.inv-close{position:absolute;top:calc(12px + env(safe-area-inset-top, 0px));left:max(12px, env(safe-area-inset-left, 0px));z-index:60;border:0;padding:8px 12px;background:rgba(0,0,0,.5);color:#fff;font-size:12px;letter-spacing:.06em;cursor:pointer;backdrop-filter:blur(6px)}
@media (prefers-reduced-motion: reduce){*{scroll-behavior:auto!important}}

/* ===== Invitation: four families (sampul, mihrab, ukiran, catair). Each design commits to one look, colours come from --c-* per design. ===== */
.inv{position:absolute;inset:0;overflow:hidden;background:var(--ground);color:var(--ink);font-family:var(--b);container-type:inline-size;-webkit-font-smoothing:antialiased;contain:paint;isolation:isolate}
/* contain:paint makes the card the containing block for any position:fixed layer inside it (texture overlays, sheets), so nothing escapes the phone preview */
.inv *{box-sizing:border-box}
.inv .scroller{position:absolute;inset:0;overflow-y:auto;overflow-x:hidden;scroll-behavior:smooth;-webkit-overflow-scrolling:touch}
.inv .tex{position:relative;isolation:isolate}
.inv .tex::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/300px;mix-blend-mode:multiply;pointer-events:none;z-index:5;opacity:.85}
.inv .linen{position:relative;isolation:isolate}
.inv .linen::before{content:"";position:absolute;inset:0;background:url(/assets/linen.jpg) 0 0/200px;mix-blend-mode:soft-light;opacity:.55;pointer-events:none;z-index:0}
.inv .fl{position:absolute;display:block;pointer-events:none;user-select:none;max-width:none}
.inv .eng{position:absolute;display:block;background:var(--ink);-webkit-mask:var(--m) center/contain no-repeat;mask:var(--m) center/contain no-repeat;pointer-events:none}
.inv .vignette{position:relative;display:block;margin:4px auto;max-width:none}
.inv .eng.vignette{background:var(--ink)}

/* type */
.inv .kicker{font-family:var(--d);text-transform:uppercase;letter-spacing:.34em;font-size:10.5px;color:var(--accent)}
.inv .names{font-family:var(--s);font-weight:400;line-height:1.02;color:var(--accent);margin:0}
.inv .names .amp{display:block;font-size:.5em;margin:.12em 0;color:var(--gold)}
.inv .caps{font-family:var(--d);text-transform:uppercase;letter-spacing:.24em;font-size:12px}
.inv .it{font-style:italic}
.inv .small{font-size:13px;opacity:.82}
.inv .rule{display:flex;align-items:center;gap:10px;width:120px;margin:4px auto;color:var(--gold)}
.inv .rule::before,.inv .rule::after{content:"";flex:1;height:1px;background:currentColor;opacity:.7}
.inv .rule i{width:6px;height:6px;transform:rotate(45deg);background:currentColor;display:block}

/* ---------- first page: the front of the card ---------- */
.inv .page{position:relative;min-height:100%;overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
/* sampul page: ivory card lying on the ground colour */
.inv .pg-sampul{padding:22px 18px;align-items:stretch}
.inv .pg-sampul .card{position:relative;flex:1;background:var(--sheet);box-shadow:0 18px 40px rgba(0,0,0,.35),0 2px 4px rgba(0,0,0,.2);overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:70px 26px}
.inv .pg-sampul .card .frame{position:absolute;inset:10px;border:1px solid var(--gold);opacity:.55;z-index:2;pointer-events:none}
.inv .pg-sampul .card > :not(.fl):not(.frame){position:relative;z-index:3}
.inv .pg-sampul .names{font-size:clamp(46px,16cqi,66px)}
.inv .pg-sampul .names .amp,.inv .pg-mihrab .names .amp{color:var(--accent);opacity:.55}
/* mihrab page: arched panel on a lattice ground */
.inv .pg-mihrab{background:var(--ground)}
.inv .lattice{position:absolute;inset:0;background-image:var(--lattice);background-size:64px;opacity:.5;z-index:0}
.inv .arch{position:absolute;left:7%;right:7%;top:7%;bottom:4%;z-index:1}
.inv .arch-fill{position:absolute;inset:0;background:var(--sheet);-webkit-mask:var(--archmask) 0 0/100% 100% no-repeat;mask:var(--archmask) 0 0/100% 100% no-repeat;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:26% 22px 30%}
.inv .arch-fill > :not(.fl){position:relative;z-index:3}
.inv .arch svg.outline{position:absolute;inset:-7px;width:calc(100% + 14px);height:calc(100% + 14px);overflow:visible;z-index:4;pointer-events:none}
.inv .keystone{position:absolute;left:50%;top:calc(7% - 22px);width:30px;transform:translateX(-50%);z-index:4;color:var(--gold)}
.inv .pg-mihrab .names{font-size:clamp(42px,14cqi,58px)}
.inv .bismillah{font-family:"Amiri",serif;font-size:24px;direction:rtl;color:var(--gold);line-height:1.5}
/* ukiran page: one ink on aged paper */
.inv .pg-ukiran{background:var(--sheet);padding:40px 30px}
.inv .pg-ukiran::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,transparent 50%,color-mix(in srgb,var(--ink) 16%,transparent));z-index:1;pointer-events:none}
.inv .border2{position:absolute;inset:14px;border:1.5px solid var(--ink);z-index:2;pointer-events:none}
.inv .border2::after{content:"";position:absolute;inset:4px;border:.6px solid var(--ink)}
.inv .pg-ukiran > :not(.eng):not(.border2){position:relative;z-index:3}
.inv .oval{width:96px;height:124px;border:1px solid var(--ink);border-radius:50%;display:flex;align-items:center;justify-content:center;margin-bottom:12px;position:relative;background:var(--sheet)}
.inv .oval::after{content:"";position:absolute;inset:4px;border:.6px solid var(--ink);border-radius:50%}
.inv .oval .jawi{font-family:"Aref Ruqaa","Amiri",serif;font-size:34px;line-height:1;direction:rtl}
.inv .oval .lat{font-family:var(--s);font-style:italic;font-size:30px}
.inv .pg-ukiran .names{font-size:clamp(38px,12.5cqi,50px);font-style:italic;color:var(--ink)}
.inv .pg-ukiran .names .amp{color:var(--ink);opacity:.7}
/* catair page: white cotton paper, painted flowers, left-set type */
.inv .pg-catair{background:var(--sheet);align-items:flex-start;text-align:left;padding:0 0 0 11%}
.inv .pg-catair .txt{position:relative;z-index:3;width:68%;display:flex;flex-direction:column;gap:12px;margin-top:-14%}
.inv .pg-catair .names{font-family:var(--d);font-weight:400;text-transform:uppercase;letter-spacing:.24em;font-size:clamp(26px,8.6cqi,36px);line-height:1.25}
.inv .pg-catair .names .amp{display:block;font-family:var(--s);font-style:italic;text-transform:none;letter-spacing:0;font-size:.85em;color:var(--ink);opacity:.75;margin:.1em 0}

/* ---------- covers: how each family opens ---------- */
.inv .cover{position:absolute;inset:0;z-index:30;transition:opacity .7s ease}
.inv.opened .cover{opacity:0;pointer-events:none}
.inv.thumb.opened .cover{display:none}
/* sampul: an envelope back with a wax seal */
.inv .cv-sampul{background:var(--ground);perspective:1400px}
.inv .env{position:absolute;inset:0}
.inv .env-inside{position:absolute;inset:0;background:var(--liner)}
.inv .env-card{position:absolute;left:9%;right:9%;top:20%;height:66%;background:var(--sheet);box-shadow:0 -4px 14px rgba(0,0,0,.18);display:flex;flex-direction:column;align-items:center;padding-top:9%;gap:6px;text-align:center;transition:transform 1s cubic-bezier(.5,0,.2,1)}
.inv .env-card .names{font-size:clamp(28px,10cqi,40px)}
.inv .env-pocket{position:absolute;inset:0;background:var(--env);clip-path:polygon(0 0,50% 52%,100% 0,100% 100%,0 100%);z-index:3}
.inv .env-pocket .fold{position:absolute;inset:0;clip-path:polygon(0 100%,50% 50%,100% 100%);background:linear-gradient(to top,rgba(255,255,255,.07),rgba(0,0,0,.08))}
.inv .env-pocket .emb{position:absolute;width:62%;opacity:.6}
.inv .env-pocket .emb .hi,.inv .env-pocket .emb .lo{position:absolute;inset:0;-webkit-mask:var(--m) center/contain no-repeat;mask:var(--m) center/contain no-repeat}
.inv .env-pocket .emb .hi{background:rgba(255,255,255,.55);transform:translate(-1px,-1px)}
.inv .env-pocket .emb .lo{background:rgba(0,0,0,.35);transform:translate(1px,1px)}
.inv .env-flap{position:absolute;left:0;right:0;top:0;height:54%;transform-origin:50% 0;transition:transform .85s .2s cubic-bezier(.6,0,.3,1);z-index:4;filter:drop-shadow(0 6px 6px rgba(0,0,0,.28));transform-style:preserve-3d}
.inv .env-flap .face{position:absolute;inset:0;background:var(--env);clip-path:polygon(0 0,100% 0,50% 100%)}
.inv .env-flap .face::after{content:"";position:absolute;inset:0;background:linear-gradient(to bottom,rgba(255,255,255,.08),rgba(0,0,0,.06))}
.inv .env .tex::after,.inv .env-pocket::after,.inv .env-flap .face::before{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/300px;mix-blend-mode:multiply;opacity:.9;pointer-events:none}
.inv .seal{position:absolute;left:50%;top:54%;width:32%;aspect-ratio:1;transform:translate(-50%,-50%);border:0;padding:0;background:var(--seal) center/contain no-repeat;cursor:pointer;z-index:6;transition:transform .5s,opacity .45s;filter:drop-shadow(0 3px 4px rgba(0,0,0,.35));display:flex;align-items:center;justify-content:center}
.inv .seal span{font-family:var(--s);font-size:clamp(20px,7cqi,30px);color:rgba(0,0,0,.28);text-shadow:0 1px 0 rgba(255,255,255,.35),0 -1px 0 rgba(0,0,0,.2);margin-top:-2%}
.inv .seal span.jw{font-family:"Aref Ruqaa","Amiri","Noto Serif TC",var(--s),serif;unicode-bidi:plaintext;white-space:nowrap;font-size:clamp(22px,7.6cqi,32px);margin-top:0}
.inv .seal:focus-visible{outline:2px solid var(--envInk);outline-offset:4px;border-radius:50%}
.inv .env-to{position:absolute;left:0;right:0;top:15%;text-align:center;z-index:5;color:var(--envInk);transition:opacity .3s}
.inv .env-to .caps{font-size:10px;opacity:.75}
.inv .env-to b{display:block;font-family:var(--s);font-weight:400;font-size:clamp(24px,8cqi,32px);margin-top:4px}
.inv .env-meta{position:absolute;left:0;right:0;bottom:11%;text-align:center;z-index:5;color:var(--envInk);display:flex;flex-direction:column;gap:8px;transition:opacity .3s}
.inv .env-meta .hint{font-family:var(--b);font-style:italic;font-size:14px;opacity:.8}
.inv.opening .seal{transform:translate(-50%,-50%) scale(1.2) rotate(-12deg);opacity:0}
.inv.opening .env-to,.inv.opening .env-meta{opacity:0}
.inv.opening .env-flap{transform:rotateX(178deg)}
.inv.card-out .env-flap{z-index:1}
.inv.card-out .env-card{transform:translateY(-34%)}
/* mihrab: carved lattice doors */
.inv .cv-mihrab{perspective:1600px;background:transparent}
.inv .door{position:absolute;top:0;bottom:0;width:50%;background:var(--door);transition:transform 1.25s cubic-bezier(.55,0,.25,1);overflow:hidden;box-shadow:inset 0 0 40px rgba(0,0,0,.35)}
.inv .door.l{left:0;transform-origin:0 50%;border-right:1px solid rgba(0,0,0,.35)}
.inv .door.r{right:0;transform-origin:100% 50%;border-left:1px solid rgba(255,255,255,.08)}
.inv .door .jali{position:absolute;inset:14% 14% 9%;border:1px solid var(--gold);border-radius:999px 999px 3px 3px/120px 120px 3px 3px;background-image:var(--lattice);background-size:30px;background-color:rgba(0,0,0,.18);box-shadow:0 0 0 5px var(--door),0 0 0 6px color-mix(in srgb,var(--gold) 60%,transparent)}
.inv .door .frame{position:absolute;inset:10px;border:1px solid color-mix(in srgb,var(--gold) 55%,transparent)}
.inv .medal{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:38%;aspect-ratio:1;border-radius:50%;border:1px solid var(--gold);background:var(--door);box-shadow:0 0 0 6px var(--door),0 0 0 7px var(--gold),0 8px 20px rgba(0,0,0,.4);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;color:var(--gold);cursor:pointer;z-index:5;transition:opacity .35s,transform .5s;font:inherit}
.inv .medal .mono{font-family:var(--s);font-size:clamp(26px,9cqi,36px);line-height:1}
.inv .medal .mono.jawi{font-family:"Aref Ruqaa","Amiri",serif;direction:rtl}
.inv .medal small{font-family:var(--d);font-size:9px;letter-spacing:.3em;text-transform:uppercase}
.inv .door-to{position:absolute;left:0;right:0;top:6%;text-align:center;color:var(--gold);z-index:5;transition:opacity .3s}
.inv .door-to b{display:block;font-family:var(--s);font-weight:400;font-size:clamp(22px,7cqi,28px);color:color-mix(in srgb,var(--gold) 80%,#fff)}
.inv.opening .door.l{transform:rotateY(-104deg)}
.inv.opening .door.r{transform:rotateY(104deg)}
.inv.opening .medal{opacity:0;transform:translate(-50%,-50%) scale(.9)}
.inv.opening .door-to{opacity:0}
/* ukiran: a sheet of vellum over the print */
.inv .cv-ukiran{transition:transform 1.1s cubic-bezier(.6,0,.25,1),opacity .6s .6s}
.inv .vellum{position:absolute;inset:0;background:color-mix(in srgb,var(--sheet) 62%,transparent);-webkit-backdrop-filter:blur(2.5px);backdrop-filter:blur(2.5px);display:flex;flex-direction:column;align-items:center;justify-content:flex-end;padding:0 24px 16%;gap:12px;text-align:center;box-shadow:0 4px 18px rgba(0,0,0,.12)}
.inv .vellum::before{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/300px;mix-blend-mode:multiply;opacity:.35}
.inv .vellum > *{position:relative}
.inv.opening .cv-ukiran{transform:translateY(-104%)}
/* catair: a tissue sheet that dissolves */
.inv .cv-catair{transition:opacity 1s ease,filter 1s ease}
.inv .tissue{position:absolute;inset:0;background:color-mix(in srgb,var(--sheet) 72%,transparent);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);display:flex;flex-direction:column;align-items:center;justify-content:flex-end;padding:0 24px 16%;gap:12px;text-align:center}
.inv.opening .cv-catair{opacity:0;filter:blur(6px)}
.inv .to-line{font-family:var(--b);font-style:italic;font-size:15px}
.inv .to-line b{display:block;font-style:normal;font-family:var(--d);letter-spacing:.14em;text-transform:uppercase;font-size:14px;margin-top:4px;font-weight:400}
.inv .open-btn{border:1px solid var(--ink);background:transparent;color:var(--ink);padding:11px 26px;font-family:var(--d);letter-spacing:.28em;text-transform:uppercase;font-size:11px;cursor:pointer}
.inv .open-btn:hover{background:var(--ink);color:var(--sheet)}

/* ---------- content sheet ---------- */
.inv .sheet{position:relative;background:var(--sheet);margin:0 12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.inv .flush .sheet,.inv.flush .sheet{margin:0;box-shadow:none}
.inv .sec{position:relative;z-index:6;padding:44px 26px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:14px}
.inv .sec + .sec{border-top:1px solid var(--line)}
.inv .sec h2{font-family:var(--d);font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--accent);font-weight:400;margin:0}
.inv .sec p{font-size:16px;line-height:1.7;max-width:32ch;margin:0}
.inv .person{font-family:var(--d);font-size:17px;letter-spacing:.06em;line-height:1.4;text-transform:uppercase}
.inv .orn{color:var(--gold);font-size:22px;line-height:1}
.inv .info{width:100%;max-width:330px;display:grid;grid-template-columns:1fr 1fr}
.inv .info > div{border-bottom:1px solid var(--line);padding:14px 8px}
.inv .info > div:last-child,.inv .info > div:nth-last-child(2):not(.full){border-bottom:0}
.inv .info .full{grid-column:1/-1}
.inv .info span{display:block;font-family:var(--d);font-size:9.5px;letter-spacing:.24em;text-transform:uppercase;opacity:.7;margin-bottom:3px}
.inv .info b{font-weight:400;font-size:17px}
.inv .ibtns{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
.inv .ibtn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:999px;color:var(--ink);background:transparent;padding:9px 16px;font-size:13px;text-decoration:none;cursor:pointer;font-family:var(--b)}
.inv .ibtn:hover{border-color:var(--accent);color:var(--accent)}
.inv .ibtn.solid{background:var(--accent);color:var(--sheet);border-color:var(--accent)}
.inv .ibtn svg{width:15px;height:15px}
.inv .count{display:grid;grid-template-columns:repeat(4,1fr);width:100%;max-width:320px}
.inv .count div{padding:6px 2px}
.inv .count div + div{border-left:1px solid var(--line)}
.inv .count b{display:block;font-family:var(--d);font-size:30px;font-weight:400;font-variant-numeric:tabular-nums;color:var(--accent)}
.inv .count span{font-size:10px;letter-spacing:.2em;text-transform:uppercase;opacity:.7}
.inv .timeline{list-style:none;margin:0;padding:0;width:100%;max-width:300px;text-align:left}
.inv .timeline li{display:grid;grid-template-columns:82px 1fr;gap:12px;padding:10px 0;border-bottom:1px dotted var(--line)}
.inv .timeline li:last-child{border-bottom:0}
.inv .timeline b{font-family:var(--d);font-weight:400;color:var(--accent);font-variant-numeric:tabular-nums;font-size:14px;letter-spacing:.06em}
.inv .gallery{display:grid;grid-template-columns:1fr 1fr;gap:8px;width:100%}
.inv .gallery img{width:100%;aspect-ratio:3/4;object-fit:cover;box-shadow:0 2px 6px rgba(0,0,0,.15)}
.inv .gallery img:first-child:nth-last-child(odd){grid-column:1/-1;aspect-ratio:4/3}
.inv form{display:flex;flex-direction:column;gap:10px;width:100%;max-width:320px;text-align:left}
.inv form label{font-family:var(--d);font-size:10px;letter-spacing:.2em;text-transform:uppercase;opacity:.75}
.inv form input,.inv form select,.inv form textarea{width:100%;padding:10px 0;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);font-family:var(--b);font-size:16px;border-radius:0}
.inv form textarea{border:1px solid var(--line);padding:10px}
.inv form input:focus,.inv form select:focus,.inv form textarea:focus{outline:none;border-color:var(--accent)}
.inv .seg{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:4px}
.inv .seg button{padding:10px;border:1px solid var(--line);background:transparent;cursor:pointer;color:var(--ink);font-family:var(--b);font-size:15px}
.inv .seg button[aria-pressed="true"]{border-color:var(--accent);background:var(--accent);color:var(--sheet)}
.inv .submit{margin-top:6px;padding:13px;border:0;background:var(--accent);color:var(--sheet);font-family:var(--d);letter-spacing:.26em;text-transform:uppercase;font-size:11px;cursor:pointer}
.inv .note{font-size:14px;padding:12px;border:1px solid var(--line);text-align:center;width:100%;max-width:320px;font-style:italic}
.inv .wishes{display:flex;flex-direction:column;width:100%;max-width:320px;max-height:330px;overflow-y:auto;text-align:left}
.inv .wish{padding:14px 0;border-bottom:1px dotted var(--line)}
.inv .wish b{font-family:var(--d);font-weight:400;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.inv .wish p{font-size:15px;margin-top:4px;max-width:none;font-style:italic}
.inv .wish time{font-size:11px;opacity:.6}
.inv .giftcard{width:100%;max-width:300px;padding:20px 16px;border:1px solid var(--line);outline:1px solid var(--line);outline-offset:4px;display:flex;flex-direction:column;gap:6px;align-items:center}
.inv .giftcard .acc{font-family:var(--d);font-size:21px;letter-spacing:.12em;font-variant-numeric:tabular-nums}
.inv .giftcard img{width:160px;height:160px;object-fit:contain;background:#fff;padding:6px;margin-top:8px}
.inv .contact{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;max-width:320px;padding:12px 0;border-bottom:1px dotted var(--line);text-align:left}
.inv .contact b{display:block;font-weight:400;font-size:17px}
.inv .contact span{font-size:13px;opacity:.75}
.inv .foot{padding:30px 20px 34px;text-align:center;font-size:12px;letter-spacing:.14em;text-transform:uppercase;opacity:.55;position:relative;z-index:6;font-family:var(--d)}
.inv .dock{position:sticky;bottom:0;z-index:20;display:grid;background:color-mix(in srgb,var(--sheet) 90%,transparent);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom, 0px)}
.inv .dock button{background:none;border:0;padding:9px 2px 8px;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10px;letter-spacing:.08em;color:var(--ink);cursor:pointer;font-family:var(--b)}
.inv .dock svg{width:18px;height:18px;color:var(--accent)}
.inv .music-btn{position:absolute;top:14px;right:14px;z-index:25;width:36px;height:36px;border-radius:50%;border:1px solid var(--line);background:color-mix(in srgb,var(--sheet) 85%,transparent);color:var(--accent);display:flex;align-items:center;justify-content:center;cursor:pointer}
.inv .music-btn svg{width:17px;height:17px}
.inv .music-btn.playing svg{animation:spin 5s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.inv .sheet-bg{position:absolute;inset:0;background:rgba(0,0,0,.35);z-index:40;display:flex;align-items:flex-end}
.inv .sheet-pop{width:100%;background:var(--sheet);color:var(--ink);padding:24px 22px calc(22px + env(safe-area-inset-bottom, 0px));display:flex;flex-direction:column;gap:12px;align-items:center;text-align:center;border-top:1px solid var(--line)}
.inv .sheet-pop h3{font-family:var(--d);font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--accent);font-weight:400;margin:0}
.inv .reveal{animation:rise 1s both}
.inv .reveal.d1{animation-delay:.15s}.inv .reveal.d2{animation-delay:.3s}.inv .reveal.d3{animation-delay:.45s}
@keyframes rise{from{transform:translateY(12px);opacity:.001}to{transform:none;opacity:1}}
.inv.thumb .reveal{animation:none}
@media (prefers-reduced-motion: reduce){.inv .reveal{animation:none}.inv .env-flap,.inv .door,.inv .cv-ukiran,.inv .env-card{transition:none}.inv .music-btn.playing svg{animation:none}}

/* ===== Round-two families: songket, tiket, herbarium, tipografi, deco, baldu, bingkai, poskad ===== */
.inv .foil{background:url(/assets/foil.jpg) 0 0/240px,var(--gold);background-blend-mode:overlay}
.inv .foil-text{background:url(/assets/foil.jpg) 0 0/240px,var(--gold);background-blend-mode:overlay;-webkit-background-clip:text;background-clip:text;color:transparent!important}
.inv .silk{position:relative;isolation:isolate}
.inv .silk::before{content:"";position:absolute;inset:0;background:url(/assets/silk.jpg) 0 0/180px;mix-blend-mode:soft-light;opacity:.7;pointer-events:none;z-index:0}
.inv .velvet{position:relative;isolation:isolate}
.inv .velvet::before{content:"";position:absolute;inset:0;background:url(/assets/velvet.jpg) 0 0/220px,radial-gradient(120% 80% at 30% 20%,rgba(255,255,255,.18),transparent 55%),radial-gradient(90% 70% at 80% 90%,rgba(0,0,0,.35),transparent 60%);mix-blend-mode:soft-light;pointer-events:none;z-index:0}
.inv .fmask{position:absolute;-webkit-mask:var(--m) var(--mp,0 0)/var(--ms,auto) var(--mr,repeat);mask:var(--m) var(--mp,0 0)/var(--ms,auto) var(--mr,repeat);pointer-events:none}

/* songket: woven gold bands on silk */
.inv .pg-songket{background:var(--ground);color:var(--pagefg)}
.inv .pg-songket .band{position:absolute;top:0;bottom:0;width:17%;z-index:2}
.inv .pg-songket .band.l{left:0}.inv .pg-songket .band.r{right:0;transform:scaleX(-1)}
.inv .pg-songket .tabur{position:absolute;inset:0 17%;z-index:1;opacity:.85}
.inv .pg-songket .mid{position:relative;z-index:3;display:flex;flex-direction:column;align-items:center;gap:12px;padding:0 22%}
.inv .pg-songket .mono{font-family:"Aref Ruqaa","Amiri",serif;font-size:46px;line-height:1.1}
.inv .pg-songket .names{font-size:clamp(40px,13cqi,54px)}
.inv .pg-songket .caps,.inv .pg-songket .small{color:var(--pagefg)}
.inv .cv-songket .cloth{position:absolute;top:0;bottom:0;width:50.5%;background:var(--ground);transition:transform 1.1s cubic-bezier(.6,0,.25,1);overflow:hidden;box-shadow:0 0 24px rgba(0,0,0,.4)}
.inv .cv-songket .cloth.l{left:0}.inv .cv-songket .cloth.r{right:0}
.inv .cv-songket .cloth .band{position:absolute;top:0;bottom:0;width:34%}
.inv .cv-songket .cloth.l .band{right:0}.inv .cv-songket .cloth.r .band{left:0;transform:scaleX(-1)}
.inv .cv-songket .clasp{position:absolute;left:50%;top:50%;width:28%;aspect-ratio:1;transform:translate(-50%,-50%);border:0;padding:0;background:var(--seal) center/contain no-repeat;cursor:pointer;z-index:4;filter:drop-shadow(0 4px 6px rgba(0,0,0,.45));transition:opacity .4s,transform .4s;display:flex;align-items:center;justify-content:center}
.inv .cv-songket .clasp span{font-family:"Aref Ruqaa","Amiri",serif;font-size:clamp(20px,7cqi,28px);color:rgba(0,0,0,.3);text-shadow:0 1px 0 rgba(255,255,255,.35)}
.inv .cv-songket .hint{position:absolute;left:0;right:0;bottom:12%;text-align:center;z-index:4;color:var(--pagefg);font-family:var(--b);font-style:italic;transition:opacity .3s}
.inv .cv-songket .to{position:absolute;left:0;right:0;top:12%;text-align:center;z-index:4;transition:opacity .3s}
.inv.opening .cv-songket .cloth.l{transform:translateX(-102%)}
.inv.opening .cv-songket .cloth.r{transform:translateX(102%)}
.inv.opening .cv-songket .clasp,.inv.opening .cv-songket .hint,.inv.opening .cv-songket .to{opacity:0}

/* tiket: passport opens on a boarding pass */
.inv .pg-tiket{background:var(--ground);padding:26px 18px}
.inv .ticket{position:relative;z-index:2;width:100%;background:var(--sheet);border-radius:14px;box-shadow:0 18px 36px rgba(0,0,0,.28);overflow:hidden;text-align:left;color:var(--ink)}
.inv .ticket .hd{background:var(--accent);color:var(--sheet);padding:14px 18px;display:flex;justify-content:space-between;align-items:center;font-family:var(--d);font-size:10.5px;letter-spacing:.2em;text-transform:uppercase}
.inv .ticket .route{display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:8px;padding:22px 18px 6px}
.inv .ticket .route b{display:block;font-family:var(--s);font-size:clamp(38px,13cqi,52px);line-height:.9;font-weight:500;letter-spacing:.02em;color:var(--accent)}
.inv .ticket .route span{font-family:var(--d);font-size:10px;letter-spacing:.16em;text-transform:uppercase;opacity:.7}
