.inv .ticket .route svg{width:54px;height:30px;color:var(--accent);margin-bottom:8px}
.inv .ticket .names-row{padding:4px 18px 14px;font-family:"Pinyon Script",cursive;font-size:clamp(26px,9cqi,34px);color:var(--ink)}
.inv .ticket .grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 16px;padding:14px 18px 18px;border-top:1px dashed var(--line)}
.inv .ticket .grid span{display:block;font-family:var(--d);font-size:9.5px;letter-spacing:.18em;text-transform:uppercase;opacity:.6}
.inv .ticket .grid b{font-family:var(--d);font-weight:500;font-size:14px;letter-spacing:.04em}
.inv .ticket .perf{position:relative;height:22px}
.inv .ticket .perf::before{content:"";position:absolute;left:14px;right:14px;top:50%;border-top:2px dotted var(--line)}
.inv .ticket .perf::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 0 50%,var(--ground) 11px,transparent 11.5px),radial-gradient(circle at 100% 50%,var(--ground) 11px,transparent 11.5px)}
.inv .ticket .stub{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 18px 18px}
.inv .ticket .stub svg.bar{height:46px;width:62%}
.inv .ticket .stub .seat{text-align:right;font-family:var(--d);font-size:10px;letter-spacing:.16em;text-transform:uppercase}
.inv .ticket .stub .seat b{display:block;font-size:26px;letter-spacing:.04em;color:var(--accent)}
.inv .cv-tiket{background:var(--ground);perspective:1600px;display:flex;align-items:center;justify-content:center}
.inv .passport{position:relative;width:74%;aspect-ratio:.7;border-radius:6px 14px 14px 6px;background:var(--cover);transform-origin:0 50%;transition:transform 1.1s cubic-bezier(.6,0,.25,1),opacity .4s .8s;box-shadow:0 22px 40px rgba(0,0,0,.4),inset 6px 0 10px rgba(0,0,0,.25);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:20px;cursor:pointer;border:0;color:inherit;font:inherit}
.inv .passport .emblem{width:42%;aspect-ratio:1;border-radius:50%;display:flex;align-items:center;justify-content:center}
.inv .passport .emblem svg{width:60%;height:60%}
.inv .passport .pt{font-family:var(--d);letter-spacing:.3em;font-size:12px;text-transform:uppercase}
.inv .passport .pn{font-family:"Pinyon Script",cursive;font-size:clamp(22px,8cqi,30px)}
.inv .cv-tiket .to{position:absolute;left:0;right:0;top:8%;text-align:center;color:var(--sheet)}
.inv .cv-tiket .hint{position:absolute;left:0;right:0;bottom:8%;text-align:center;color:var(--sheet);font-style:italic;font-family:"Cormorant Garamond",serif;font-size:15px}
.inv.opening .passport{transform:rotateY(-150deg);opacity:0}
.inv.opening .cv-tiket .to,.inv.opening .cv-tiket .hint{opacity:0;transition:opacity .3s}

/* herbarium: a pressed flower on handmade paper */
.inv .pg-herb{background:var(--ground);padding:24px 18px}
.inv .herb-sheet{position:relative;z-index:2;width:100%;min-height:calc(100% - 0px);flex:1;align-self:stretch;background:var(--sheet);-webkit-mask:url(/assets/deckle.png) 0 0/100% 100%;mask:url(/assets/deckle.png) 0 0/100% 100%;display:flex;flex-direction:column;align-items:center;padding:34px 24px 30px;gap:12px}
.inv .pg-herb{align-items:stretch}
.inv .herb-sheet .press{position:relative;width:64%;margin-top:4px}
