.inv .tape{position:absolute;height:24px;width:46%;background:var(--tape);opacity:.78;mix-blend-mode:multiply;clip-path:polygon(0 8%,4% 0,8% 10%,12% 0,100% 0,96% 12%,100% 25%,96% 40%,100% 55%,96% 70%,100% 88%,96% 100%,0 100%,4% 85%,0 70%,4% 52%,0 35%,4% 20%)}
.inv .label{position:relative;z-index:3;border:1px solid var(--ink);padding:10px 12px;font-family:"Special Elite","Courier New",monospace;font-size:11.5px;line-height:1.55;text-align:left;width:86%;background:color-mix(in srgb,var(--sheet) 85%,#fff)}
.inv .label .lt{display:flex;justify-content:space-between;border-bottom:1px solid var(--ink);padding-bottom:4px;margin-bottom:6px;letter-spacing:.1em;text-transform:uppercase}
.inv .pg-herb .names{font-family:"Homemade Apple",cursive;font-size:clamp(26px,8.6cqi,34px);color:var(--accent);line-height:1.5}
.inv .pg-herb .names .amp{display:inline;font-size:.7em;margin:0 .2em;color:var(--ink)}
.inv .cv-herb{transition:transform 1.1s cubic-bezier(.6,0,.25,1),opacity .5s .6s}
.inv .glassine{position:absolute;inset:0;background:color-mix(in srgb,#fff 52%,transparent);-webkit-backdrop-filter:blur(3px) saturate(.85);backdrop-filter:blur(3px) saturate(.85);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;border-top:1px solid rgba(255,255,255,.7)}
.inv .glassine .sticker{background:var(--sheet);border:1px solid var(--ink);padding:14px 22px;font-family:"Special Elite","Courier New",monospace;font-size:12px;letter-spacing:.06em;box-shadow:0 2px 6px rgba(0,0,0,.12);transform:rotate(-2deg)}
.inv .glassine .sticker b{display:block;font-family:"Homemade Apple",cursive;font-weight:400;font-size:18px;margin-top:6px;color:var(--accent)}
.inv.opening .cv-herb{transform:translateY(104%)}

/* tipografi: the date set large */
.inv .pg-tipo{background:var(--ground);color:var(--pageInk);align-items:stretch;justify-content:space-between;text-align:left;padding:46px 26px 40px}
.inv .pg-tipo .top{display:flex;justify-content:space-between;font-family:var(--d);font-size:10px;letter-spacing:.24em;text-transform:uppercase}
.inv .pg-tipo .nums{font-family:var(--s);font-weight:400;font-size:clamp(110px,40cqi,160px);line-height:.82;letter-spacing:-.04em;text-align:right;color:var(--pageAccent);font-variant-numeric:lining-nums}
.inv .pg-tipo .who{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:end;border-top:1px solid var(--pageInk);padding-top:14px}
.inv .pg-tipo .who .names{font-family:var(--s);font-style:italic;font-size:clamp(30px,10cqi,40px);color:var(--pageInk);line-height:1}
.inv .pg-tipo .who .names .amp{display:inline;font-size:.8em;margin:0 .1em;color:var(--pageAccent)}
