/* the gilt-edged name card resting on the ribbon */
.inv .ags-label{position:absolute;left:12%;right:12%;top:61%;display:flex;flex-direction:column;align-items:center;gap:5px;padding:16px 10px 14px;transform:rotate(-1.4deg);color:var(--ink);text-align:center;
  background:radial-gradient(80% 60% at 30% 10%,rgba(255,255,255,.6),transparent),url(/assets/paper.jpg) 0 0/220px,var(--sheet);background-blend-mode:normal,multiply,normal;
