.fam-bulan.cardsecs .sec{background:var(--sheet);margin:0 14px;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--gold) 80%,transparent),inset 0 0 0 5px var(--sheet),inset 0 0 0 5.6px color-mix(in srgb,var(--gold) 45%,transparent),0 16px 30px rgba(0,0,0,.32);isolation:isolate}
.fam-bulan.cardsecs .sec:first-child{margin-top:16px}
.fam-bulan .sec::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/300px;mix-blend-mode:multiply;opacity:.45;pointer-events:none;z-index:-1}
.fam-bulan .sec h2{display:flex;flex-direction:column;align-items:center;gap:9px;font-family:var(--d);letter-spacing:.3em;color:var(--accent)}
.fam-bulan .sec h2::after{content:"";width:44px;height:3px;background:radial-gradient(circle,var(--gold) .9px,transparent 1.3px) 0 0/11px 3px repeat-x}
.fam-bulan .bln-h{width:22px;height:22px;background:url(/assets/foil.jpg) 0 0/200px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--bln-cres) center/contain no-repeat;mask:var(--bln-cres) center/contain no-repeat;transform:rotate(-24deg)}
.fam-bulan .bln-div{display:flex;align-items:center;justify-content:center;gap:9px;height:46px;padding:0 22%}
.fam-bulan .bln-div i{flex:1;height:1px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--gold) 80%,transparent))}
.fam-bulan .bln-div i:last-child{background:linear-gradient(-90deg,transparent,color-mix(in srgb,var(--gold) 80%,transparent))}
.fam-bulan .bln-div b{width:3px;height:3px;border-radius:50%;background:var(--gold)}
.fam-bulan .bln-div s{width:16px;height:16px;background:url(/assets/foil.jpg) 0 0/200px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--bln-star) center/contain no-repeat;mask:var(--bln-star) center/contain no-repeat}
.fam-bulan .info,.fam-bulan .info > div{border-color:color-mix(in srgb,var(--gold) 45%,transparent)}
.fam-bulan .timeline b,.fam-bulan .count b{color:var(--accent)}
.fam-bulan .count div + div{border-left-color:color-mix(in srgb,var(--gold) 50%,transparent)}
.fam-bulan .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .bln-glow{animation:none}.inv .bln-se,.inv .bln-le,.inv .cv-bulan{transition:none}}
.inv .bln-lt .bln-k{color:var(--accent)}

/* ===== bungaraya: botanical plate in a bevel-cut mount ===== */
.inv .br-ground{position:absolute;inset:0;background:var(--ground);overflow:hidden}
.inv .br-ground::before{content:"";position:absolute;inset:0;background:url(/assets/linen.jpg) 0 0/220px;mix-blend-mode:multiply;opacity:.22}
.inv .br-ground::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 80% 60% at 50% 40%,rgba(255,255,255,.35),transparent 70%),linear-gradient(180deg,transparent 60%,rgba(60,40,20,.12))}
.inv .br-dk .br-ground::before{background:url(/assets/velvet.jpg) 0 0/200px;mix-blend-mode:soft-light;opacity:.5}
.inv .br-dk .br-ground::after{background:radial-gradient(ellipse 75% 55% at 50% 40%,rgba(255,255,255,.07),transparent 70%),radial-gradient(ellipse at 50% 50%,transparent 50%,rgba(0,0,0,.45))}
.inv .br-k{font-family:"Cormorant Garamond",serif;font-size:9.5px;letter-spacing:.36em;text-transform:uppercase;font-weight:500}

/* the plate: cotton paper, a pressed plate mark, the print and its caption */
.inv .br-plate{position:absolute;inset:0;background:linear-gradient(rgba(255,255,255,.72),rgba(255,255,255,.72)),url(/assets/paper.jpg) 0 0/420px,var(--sheet);background-blend-mode:normal,multiply,normal;color:var(--ink);
  box-shadow:0 1px 2px rgba(40,28,18,.25),0 18px 30px -12px rgba(30,20,12,.45)}
.inv .br-mark{position:absolute;inset:4.5% 6%;box-shadow:inset 1px 1px 0 rgba(255,255,255,.9),inset -1px -1px 0 rgba(255,255,255,.7),0 0 0 1px rgba(80,60,40,.10),1px 1px 2px rgba(80,60,40,.10)}
.inv .br-print{position:absolute;left:0;right:0;top:0;height:64%}
.inv .br-print img{position:absolute;left:4%;top:-1%;width:94%;height:auto;mix-blend-mode:multiply;filter:brightness(1.05) saturate(1.05);
  -webkit-mask:linear-gradient(180deg,#000 80%,transparent 90%);mask:linear-gradient(180deg,#000 80%,transparent 90%)}
.inv .br-cap{position:absolute;left:0;right:0;bottom:4%;text-align:center;display:flex;flex-direction:column;align-items:center}
.inv .br-cap .br-k{color:var(--accent)}
.inv .br-names{font-family:"Pinyon Script",cursive;font-size:clamp(28px,9cqi,36px);line-height:1.12;margin:4px 0 2px;color:var(--ink)}
.inv .br-names span{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.5em;color:var(--accent);margin:0 .3em}
.inv .br-date{font-family:"Cormorant Garamond",serif;font-size:10.5px;letter-spacing:.24em;text-transform:uppercase;color:var(--ink);opacity:.85}
.inv .br-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:13.5px;margin-top:2px;opacity:.8}

/* the mount: coloured board with a window, white bevelled core at the cut */
.inv .br-mat{position:absolute;inset:0;transform-style:preserve-3d;transform-origin:0 50%}
.inv .br-face,.inv .br-backface{position:absolute;inset:0;-webkit-backface-visibility:hidden;backface-visibility:hidden}
.inv .br-face{background:linear-gradient(160deg,rgba(255,255,255,.09),rgba(0,0,0,.10)),url(/assets/paper.jpg) 0 0/300px,var(--mat);background-blend-mode:normal,multiply,normal;
  -webkit-mask:linear-gradient(#000 0 0) 50% 18.2%/76% 56% no-repeat,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) 50% 18.2%/76% 56% no-repeat exclude,linear-gradient(#000 0 0);
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.12)}
.inv .br-win{position:absolute;left:12%;top:8%;width:76%;height:56%;box-sizing:border-box;border:solid 5px;border-color:#e4dccb #f3eee3 #fdfbf6 #d9d0bd;-webkit-backface-visibility:hidden;backface-visibility:hidden;
  box-shadow:inset 0 0 6px rgba(60,40,20,.25)}
.inv .br-backface{transform:rotateY(180deg);background:#f4f0e6 url(/assets/paper.jpg) 0 0/300px;background-blend-mode:multiply}
.inv .br-mcap{position:absolute;left:0;right:0;top:66.5%;bottom:3%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--mfg)}
.inv .br-mcap .br-k{font-size:10px;letter-spacing:.34em}
.inv .br-mn{font-family:"Pinyon Script",cursive;font-size:clamp(30px,9.6cqi,38px);line-height:1.15;margin:4px 0 4px;white-space:nowrap}
.inv .br-mn span{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.5em}
.inv .br-md{font-family:"Cormorant Garamond",serif;font-size:11px;letter-spacing:.32em;font-weight:500}
/* letterpressed ink on the board, or hot gold foil */
.inv .br-mcap > *{text-shadow:0 1px 0 rgba(255,255,255,.28),0 -1px 0 rgba(0,0,0,.18)}
.inv .br-foil .br-mcap > *,.inv .br-foil .br-mcap span{color:transparent;text-shadow:none;background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-background-clip:text;background-clip:text;
  filter:drop-shadow(0 1px 0 rgba(0,0,0,.25))}

/* cover */
.inv .cv-bungaraya{overflow:hidden;transition:opacity .5s ease 1.05s}
.inv .br-stage{position:absolute;left:8%;right:8%;top:8.5%;aspect-ratio:.73;perspective:1500px;transform:rotate(-.6deg)}
.inv .br-swing{transition:transform 1.25s cubic-bezier(.45,.05,.25,1);filter:drop-shadow(0 6px 8px rgba(30,20,12,.3))}
.inv .br-foot{position:absolute;left:0;right:0;bottom:6.5%;display:flex;flex-direction:column;align-items:center;gap:14px;color:var(--pagefg);transition:opacity .4s}
.inv .br-to{text-align:center}
.inv .br-to small{display:block;font-family:"Cormorant Garamond",serif;font-size:9.5px;letter-spacing:.3em;text-transform:uppercase;opacity:.75}
.inv .br-to b{font-family:"Pinyon Script",cursive;font-weight:400;font-size:26px;line-height:1.2}
.inv .br-open{cursor:pointer;border:1px solid color-mix(in srgb,var(--pagefg) 45%,transparent);background:color-mix(in srgb,var(--ground) 70%,transparent);color:var(--pagefg);
  padding:12px 34px;border-radius:999px;font-family:"Cormorant Garamond",serif;font-size:12px;font-weight:500;letter-spacing:.3em;text-transform:uppercase}
.inv.opening .br-swing{transform:rotateY(-168deg)}
.inv.opening .br-foot{opacity:0}
.inv.opening .cv-bungaraya{opacity:0}

/* page: the plate lying on the opened mount */
.inv .pg-bungaraya{background:var(--ground);color:var(--pagefg);padding:34px 0 92px;gap:18px;overflow:hidden}
.inv .pg-bungaraya > .reveal{position:relative;z-index:2}
.inv .br-lay{position:relative;width:84%;max-width:350px;aspect-ratio:.74}
.inv .br-lay .br-plate{transform:rotate(1.2deg)}
.inv .br-lay .br-under{transform:translate(-7%,2.5%) rotate(-4deg);filter:drop-shadow(0 10px 14px rgba(30,20,12,.35))}
.inv .br-lay .br-under .br-mcap{display:none}
/* with a couple photo: it takes the middle of the print, the hibiscus moves to the corner */
.inv .pg-bungaraya .br-cap .couple-ph{position:absolute;bottom:calc(100% + 12px);left:50%;transform:translateX(-50%);width:44%;margin:0;box-shadow:0 0 0 4px var(--sheet),0 0 0 5px color-mix(in srgb,var(--accent) 35%,transparent),0 8px 14px -6px rgba(30,20,12,.4)}
.inv .pg-bungaraya .br-plate:has(.couple-ph) .br-print img{width:62%;left:-12%;top:-8%;transform:rotate(-12deg)}
.inv .br-pill{flex:0 0 auto;width:auto!important;padding:11px 32px;border-radius:999px;border:1px solid color-mix(in srgb,var(--pagefg) 45%,transparent);color:var(--pagefg);text-decoration:none;
  font-family:"Cormorant Garamond",serif;font-size:12px;font-weight:500;letter-spacing:.3em;text-transform:uppercase}

/* skin: plate-paper cards with a pressed plate mark and a small engraved sprig over each heading */
.fam-bungaraya .scroller{background:var(--ground)}
.fam-bungaraya .scroller::before{content:"";position:fixed;inset:0;pointer-events:none;background:url(/assets/linen.jpg) 0 0/220px;mix-blend-mode:multiply;opacity:.18}
.fam-bungaraya.br-dark .scroller::before{background:url(/assets/velvet.jpg) 0 0/200px;mix-blend-mode:soft-light;opacity:.45}
.fam-bungaraya.cardsecs .sec{background:linear-gradient(rgba(255,255,255,.7),rgba(255,255,255,.7)),url(/assets/paper.jpg) 0 0/420px,var(--sheet);background-blend-mode:normal,multiply,normal;color:var(--ink);border-radius:1px;
  box-shadow:inset 0 0 0 14px var(--sheet),inset 1px 1px 0 15px rgba(255,255,255,.9),inset 0 0 0 15px rgba(80,60,40,.12),0 14px 24px -10px rgba(30,20,12,.4)}
.fam-bungaraya .sec,.fam-bungaraya .sec p,.fam-bungaraya .info b{color:var(--ink)}
.fam-bungaraya .br-sprig{display:block;width:34px;height:42px;margin:0 auto -4px;background:var(--accent);opacity:.8;-webkit-mask:var(--m) center/contain no-repeat;mask:var(--m) center/contain no-repeat}
.fam-bungaraya .sec h2{font-family:"Cormorant Garamond",serif;font-style:italic;font-weight:500;text-transform:none;letter-spacing:.02em;font-size:27px;color:var(--accent)}
.fam-bungaraya .info,.fam-bungaraya .info > div{border:0!important;background:none!important}
.fam-bungaraya .info > div{border-bottom:1px solid color-mix(in srgb,var(--ink) 14%,transparent)!important;padding:13px 6px!important}
.fam-bungaraya .info > div:last-child{border-bottom:0!important}
.fam-bungaraya .info span{color:var(--accent);letter-spacing:.2em}
.fam-bungaraya .ibtn{border-radius:999px;border-color:color-mix(in srgb,var(--accent) 45%,transparent);color:var(--accent);background:transparent}
