.fam-bungaraya .dock{background:color-mix(in srgb,var(--sheet) 94%,transparent);color:var(--ink);backdrop-filter:blur(6px)}
.fam-bungaraya .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .br-swing{transition:none}.inv .cv-bungaraya{transition:opacity .3s}}

/* ===== bungatelur ===== */
