/* ---- cover: a stationery card ---- */
.inv .cv-bungatelur{background:var(--ground);overflow:hidden;transition:opacity .8s .6s}
.inv .bt-paper{position:absolute;inset:8px;background:radial-gradient(ellipse 80% 60% at 50% 40%,var(--sheet) 40%,color-mix(in srgb,var(--sheet) 92%,var(--ground))),var(--sheet);box-shadow:0 10px 30px rgba(0,0,0,.35)}
.inv .bt-paper::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/300px;mix-blend-mode:multiply;opacity:.8}
