/* ---- page ---- */
.inv .pg-bungatelur{background:var(--ground);padding:10px;align-items:stretch}
.inv .bt-card{position:relative;flex:1;background:var(--sheet);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:40px 60px 50px;text-align:center;color:var(--ink);overflow:hidden;box-shadow:inset 0 0 0 9px var(--sheet),inset 0 0 0 10px color-mix(in srgb,var(--gold) 75%,transparent),inset 0 0 0 14px var(--sheet),inset 0 0 0 14.6px color-mix(in srgb,var(--gold) 45%,transparent)}
