/* skin: perforated sheets with a cloth binding strip, calendar-tab headings */
.fam-kalendar .scroller{background:repeating-linear-gradient(90deg,rgba(255,255,255,.03) 0 14px,transparent 14px 28px) local,var(--ground)}
.fam-kalendar.cardsecs .sec{margin:0 16px 22px;background:var(--sheet);padding-top:48px;box-shadow:0 2px 0 -.5px var(--sheet),0 3px 0 -.5px rgba(0,0,0,.16),0 5px 0 -1px var(--sheet),0 6px 0 -1px rgba(0,0,0,.16),0 14px 22px rgba(0,0,0,.25);isolation:isolate}
.fam-kalendar.cardsecs .sec:first-child{margin-top:24px}
.fam-kalendar .sec::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/280px;mix-blend-mode:multiply;opacity:.5;pointer-events:none;z-index:-1}
.fam-kalendar .kl-sbind{position:absolute;left:-6px;right:-6px;top:-8px;height:20px;border-radius:3px;background:linear-gradient(180deg,rgba(255,255,255,.18),transparent 40%,rgba(0,0,0,.25)),var(--bind);box-shadow:0 3px 4px rgba(0,0,0,.3)}
.fam-kalendar .kl-sbind::before,.fam-kalendar .kl-sbind::after{content:"";position:absolute;top:5px;width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#fff7d8,var(--gold) 55%,#4a3a1a)}
.fam-kalendar .kl-sbind::before{left:20%}.fam-kalendar .kl-sbind::after{right:20%}
.fam-kalendar .sec::before{content:"";position:absolute;top:18px;left:10px;right:10px;height:3px;background:radial-gradient(circle,color-mix(in srgb,var(--ink) 35%,transparent) .9px,transparent 1.2px) 0 0/6px 3px repeat-x}
.fam-kalendar .kl-tab{display:flex;flex-direction:column;width:52px;background:var(--sheet);box-shadow:0 0 0 1px color-mix(in srgb,var(--ink) 18%,transparent),0 3px 6px rgba(0,0,0,.14);transform:rotate(-2deg);margin-bottom:-2px}
.fam-kalendar .kl-tab b{background:var(--accent);color:var(--sheet);font-family:var(--d);font-weight:500;font-size:9px;letter-spacing:.2em;text-transform:uppercase;padding:3px 0 2px;padding-left:.2em}
.fam-kalendar .kl-tab span{font-family:'Abril Fatface',serif;font-size:24px;line-height:1.25;color:var(--ink)}
.fam-kalendar .sec h2{font-family:var(--d);font-weight:500;font-size:14px;letter-spacing:.3em;color:var(--accent);padding-bottom:10px;border-bottom:1.5px solid var(--accent);box-shadow:0 2.5px 0 var(--sheet),0 3.3px 0 color-mix(in srgb,var(--accent) 55%,transparent)}
.fam-kalendar .info,.fam-kalendar .info > div{border-color:color-mix(in srgb,var(--ink) 20%,transparent)}
.fam-kalendar .count b{font-family:'Abril Fatface',serif}
.fam-kalendar .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .kl-sheet,.inv .cv-kalendar{transition:none}}

/* ===== kalkir ===== */
.inv .cv-kalkir,.inv .pg-kalkir,.fam-kalkir{--gl:color-mix(in srgb,var(--gold) 75%,#fff6e0);--gd:color-mix(in srgb,var(--gold) 50%,#2e1c02);--gm:color-mix(in srgb,var(--gold) 75%,#3a2404);
  --vel:rgba(255,255,255,.22);--velb:rgba(255,255,255,.8)}
.inv .klk-dark,.fam-kalkir.klk-dark{--vel:rgba(244,244,240,.24)}
.inv .klk-bed{position:absolute;inset:0;overflow:hidden;
  background:radial-gradient(ellipse 85% 60% at 30% 15%,color-mix(in srgb,var(--ground) 82%,#fff),transparent 72%),linear-gradient(165deg,var(--ground),color-mix(in srgb,var(--ground) 84%,#000))}
.inv .klk-bed::after{content:"";position:absolute;inset:0;background:url(/assets/linen.jpg) 0 0/220px;mix-blend-mode:soft-light;opacity:.5}
/* gold printing on the cotton */
.inv .klk-gold{background:linear-gradient(115deg,var(--gd),var(--gm) 20%,var(--gold) 32%,var(--gl) 40%,var(--gm) 52%,var(--gd) 66%,var(--gm) 82%,var(--gold));
  -webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}

/* the cotton card: deckled on all four edges, thick, with a soft shadow */
.inv .klk-card{position:absolute;filter:drop-shadow(0 1px 1px rgba(0,0,0,.18)) drop-shadow(0 8px 12px rgba(20,14,6,.22))}
.inv .klk-in{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;text-align:center;color:var(--ink);
  background:linear-gradient(140deg,rgba(255,255,255,.4),transparent 45%,rgba(0,0,0,.04)),url(/assets/paper.jpg) 0 0/230px,var(--sheet);background-blend-mode:normal,multiply,normal;
  -webkit-mask:url(/assets/deckle.png) center/100% 100% no-repeat;mask:url(/assets/deckle.png) center/100% 100% no-repeat}
.inv .klk-k{font-family:"Cormorant Garamond",serif;font-weight:700;font-size:9.5px;letter-spacing:.38em;padding-left:.38em;text-transform:uppercase;color:var(--accent)}
.inv .klk-names{font-family:"Mrs Saint Delafield",cursive;font-weight:400;font-size:clamp(52px,16.5cqi,68px);line-height:.86;color:var(--accent);display:flex;flex-direction:column;align-items:center;margin:14px 0 4px;overflow-wrap:anywhere}
.inv .klk-names span{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.3em;line-height:1.4;color:var(--gold)}
/* the date as gold numerals divided by fine vertical rules */
.inv .klk-num{font-family:"Cormorant Garamond",serif;font-weight:500;font-size:clamp(28px,8.6cqi,36px);line-height:1;letter-spacing:.06em;display:flex;align-items:center;gap:12px}
.inv .klk-num i{display:block;width:1px;height:.8em;background:var(--gold);opacity:.7}
.inv .klk-cv{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:15px;margin-top:6px}
.inv .klk-flower{position:absolute;height:auto;pointer-events:none;filter:drop-shadow(1px 2px 1.5px rgba(40,28,14,.3))}

/* cover: the envelope */
.inv .cv-kalkir{background:var(--ground);overflow:hidden;transition:opacity .45s 1.2s}
.inv .klk-env{position:absolute;left:8%;width:84%;top:9%;aspect-ratio:.7;z-index:3;perspective:1100px;transform:rotate(1.6deg)}
.inv .klk-env > div{position:absolute}
.inv .klk-back{inset:0;border-radius:2px;background:color-mix(in srgb,var(--sheet) 30%,transparent);box-shadow:inset 0 0 0 1px var(--velb),0 18px 26px -10px rgba(20,14,6,.42),0 2px 4px rgba(20,14,6,.15)}
.inv .klk-ccard{left:7%;right:7%;top:5%;bottom:5%;z-index:2;transition:transform .75s cubic-bezier(.3,.1,.2,1) .7s}
.inv .klk-ccard .klk-in{padding-top:7%}
.inv .klk-ccard .klk-names{font-size:clamp(46px,14.5cqi,58px);margin-top:8px;color:color-mix(in srgb,var(--accent) 55%,#120c06);-webkit-text-stroke:.5px color-mix(in srgb,var(--accent) 55%,#120c06)}
.inv .klk-ccard .klk-k{color:color-mix(in srgb,var(--accent) 60%,#120c06)}
.inv .klk-ccard .klk-num{margin-top:auto;margin-bottom:29%;font-size:clamp(24px,7.4cqi,30px)}
.inv .klk-cflower{width:30%;left:-9%;top:44%;transform:rotate(62deg) scaleX(-1)}
/* vellum: frosted, with a little blur of what lies under it */
.inv .klk-pocket{inset:0;z-index:3;border-radius:2px;background:var(--vel);-webkit-backdrop-filter:blur(.7px);backdrop-filter:blur(.7px);box-shadow:inset 0 0 0 1px var(--velb)}
.inv .klk-folds{position:absolute;inset:0;width:100%;height:100%;display:block}
.inv .klk-env .klk-flap{left:0;right:0;top:0;height:58%;z-index:4;transform-origin:50% 0;transform-style:preserve-3d;
  transition:transform .6s cubic-bezier(.4,0,.2,1) .25s,z-index 0s .55s;filter:drop-shadow(0 2px 2px rgba(0,0,0,.14))}
.inv .klk-flap i{position:absolute;inset:0;clip-path:polygon(0 0,100% 0,50% 100%);background:linear-gradient(180deg,rgba(255,255,255,.1),rgba(255,255,255,.3));
  -webkit-backdrop-filter:blur(.8px);backdrop-filter:blur(.8px)}
/* the cotton address label */
.inv .klk-label{left:15%;right:15%;bottom:7%;z-index:5;padding:11px 8px 10px;display:flex;flex-direction:column;align-items:center;gap:2px;text-align:center;color:var(--ink);transform:rotate(-1.2deg);
  background:url(/assets/paper.jpg) 0 0/200px,var(--sheet);background-blend-mode:multiply;box-shadow:0 1px 2px rgba(20,14,6,.25),0 4px 8px -3px rgba(20,14,6,.25)}
.inv .klk-label::before{content:"";position:absolute;inset:4px;border:1px solid color-mix(in srgb,var(--gold) 60%,transparent);outline:.5px solid color-mix(in srgb,var(--gold) 40%,transparent);outline-offset:-3px;pointer-events:none}
.inv .klk-label small{font-family:"Cormorant Garamond",serif;font-weight:700;font-size:8.5px;letter-spacing:.3em;padding-left:.3em;text-transform:uppercase;color:var(--accent)}
.inv .klk-label b{font-family:"Mrs Saint Delafield",cursive;font-weight:400;font-size:clamp(27px,8.6cqi,34px);line-height:1.05;max-width:100%;overflow-wrap:anywhere}
/* the wax seal at the flap's tip: the button */
.inv .klk-seal{position:absolute;left:50%;top:58%;width:21%;aspect-ratio:1;transform:translate(-50%,-50%);z-index:7;border:0;padding:0;cursor:pointer;
  background:center/contain no-repeat;filter:drop-shadow(0 4px 5px rgba(30,20,10,.42));display:flex;align-items:center;justify-content:center;transition:opacity .35s,transform .45s}
.inv .klk-seal span{font-family:"Mrs Saint Delafield",cursive;font-size:clamp(22px,7cqi,28px);color:rgba(0,0,0,.36);text-shadow:0 1px 0 rgba(255,255,255,.35),0 -1px 0 rgba(0,0,0,.25);line-height:1;padding-top:6%}
.inv .klk-seal span i{font-style:normal;font-family:"Cormorant Garamond",serif;font-size:.5em;margin:0 1px}
.inv .klk-seal .klk-jw{font-family:"Amiri",serif;font-size:.8em}
/* the RSVP card lying under the envelope */
.inv .klk-rsvp{position:absolute;left:5%;width:58%;top:62%;aspect-ratio:1.4;z-index:2;transform:rotate(-8deg);display:flex;align-items:flex-end;justify-content:center;padding-bottom:9%;
  background:url(/assets/paper.jpg) 0 0/220px,var(--sheet);background-blend-mode:multiply;-webkit-mask:url(/assets/deckle.png) center/100% 100% no-repeat;mask:url(/assets/deckle.png) center/100% 100% no-repeat;transition:opacity .5s .4s}
.inv .klk-rsvp b{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:15px;letter-spacing:.3em;color:var(--accent)}
.inv .klk-hint{position:absolute;left:0;right:0;bottom:5.5%;z-index:4;text-align:center;font-family:"Cormorant Garamond",serif;font-weight:700;font-size:11px;letter-spacing:.34em;padding-left:.34em;text-transform:uppercase;color:var(--pagefg);transition:opacity .35s}
.inv .klk-hint::before{content:"";display:block;width:1px;height:22px;margin:0 auto 10px;background:currentColor;opacity:.5}
/* opening: the seal lifts, the vellum flap folds back, the card slides up out of the envelope */
.inv.opening .klk-seal{opacity:0;transform:translate(-50%,-80%) scale(.9)}
.inv.opening .klk-env .klk-flap{transform:rotateX(178deg);z-index:1}
.inv.opening .klk-ccard{transform:translateY(-64%)}
.inv.opening .klk-hint,.inv.opening .klk-rsvp{opacity:0}
.inv.opening .cv-kalkir{opacity:0}

/* page: the card out on the table, the opened envelope behind it */
.inv .pg-kalkir{background:var(--ground);padding:40px 0 100px;overflow:hidden}
.inv .pg-kalkir > .klk-lay{position:relative;z-index:2;width:84%;max-width:340px}
.inv .klk-penv{position:absolute;left:12%;right:-14%;top:-24px;height:62%;transform:rotate(7deg);border-radius:2px;background:var(--vel);box-shadow:inset 0 0 0 1px var(--velb),0 12px 20px -8px rgba(20,14,6,.35)}
.inv .klk-pflap{position:absolute;left:0;right:0;bottom:100%;height:52%;clip-path:polygon(0 100%,100% 100%,50% 0);background:var(--vel);box-shadow:inset 0 0 0 1px var(--velb)}
.inv .klk-pseal{position:absolute;left:50%;top:-14%;width:20%;aspect-ratio:1;transform:translateX(-50%) rotate(-20deg);background:center/contain no-repeat;filter:drop-shadow(0 3px 4px rgba(0,0,0,.35));clip-path:polygon(0 0,100% 0,100% 62%,60% 55%,40% 70%,0 60%)}
.inv .klk-pcard{position:relative;transform:rotate(-1.6deg);z-index:2}
.inv .klk-pcard .klk-in{position:relative;padding:40px 22px 34px;min-height:min(128cqi,520px);justify-content:center}
.inv .klk-pflower{width:44%;left:-8%;top:-6%;transform:rotate(-30deg) scaleX(-1)}
.inv .klk-pcard .klk-num{margin:8px 0 8px}
.inv .klk-date{font-family:"Cormorant Garamond",serif;font-weight:700;font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--accent)}
.inv .klk-hj{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:14px;margin-top:3px;opacity:.8}
.inv .klk-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:17px;margin-top:8px;max-width:24ch;line-height:1.25}
.inv .klk-bis{font-family:"Amiri",serif;font-size:15px;margin-bottom:6px}
.inv .klk-photo{width:46%;aspect-ratio:4/5;object-fit:cover;object-position:50% 30%;display:block;margin:0 auto 14px;flex:none;border-radius:2px;box-shadow:0 0 0 4px var(--sheet),0 0 0 5px color-mix(in srgb,var(--gold) 60%,transparent)}
.inv .pg-kalkir .couple-ph.front{display:none}
/* a vellum tag with a gold eyelet */
.inv .klk-tag{position:relative;z-index:3;display:flex;flex-direction:column;align-items:center;gap:1px;width:68%;margin:-30px -6% 0 auto;padding:12px 10px 12px 26px;white-space:nowrap;transform:rotate(3deg);text-decoration:none;color:var(--ink);cursor:pointer;
  background:radial-gradient(ellipse 70% 80% at 55% 50%,rgba(255,255,255,.94),rgba(255,255,255,.8) 70%,rgba(255,255,255,.62)),var(--vel);-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px);
  clip-path:polygon(16px 0,100% 0,100% 100%,16px 100%,0 50%);filter:drop-shadow(0 5px 6px rgba(20,14,6,.28))}
.inv .klk-eye{position:absolute;left:12px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:var(--ground);box-shadow:0 0 0 2px var(--gold)}
.inv .klk-tag small{font-family:"Cormorant Garamond",serif;font-weight:700;font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:var(--accent)}
.inv .klk-tag b{font-family:"Mrs Saint Delafield",cursive;font-weight:400;font-size:33px;line-height:1.05;color:var(--ink);text-shadow:0 0 .4px var(--ink)}

/* skin: cotton cards with a vellum strip behind each script heading */
.fam-kalkir .scroller{background:linear-gradient(170deg,color-mix(in srgb,var(--ground) 90%,#fff),var(--ground) 45%,color-mix(in srgb,var(--ground) 88%,#000))}
.fam-kalkir .scroller::before{content:"";position:fixed;inset:0;pointer-events:none;background:url(/assets/linen.jpg) 0 0/220px;mix-blend-mode:soft-light;opacity:.45}
.fam-kalkir.cardsecs .sec{background:linear-gradient(140deg,rgba(255,255,255,.35),transparent 45%),url(/assets/paper.jpg) 0 0/230px,var(--sheet);background-blend-mode:normal,multiply,normal;color:var(--ink);
  border-radius:2px;padding-top:30px;padding-bottom:34px;box-shadow:0 1px 1px rgba(0,0,0,.12),0 14px 24px -12px rgba(20,14,6,.4)}
.fam-kalkir .sec h2{position:relative;isolation:isolate;font-family:"Mrs Saint Delafield",cursive;font-weight:400;font-size:46px;letter-spacing:0;text-transform:none;line-height:1.1;color:var(--accent);padding:6px 0 2px}
.fam-kalkir .sec h2::before{content:"";position:absolute;left:-30px;right:-30px;top:8px;bottom:6px;z-index:-1;transform:rotate(-1deg);
  background:linear-gradient(rgba(255,255,255,.6),rgba(255,255,255,.42)),color-mix(in srgb,var(--ground) 16%,transparent);box-shadow:inset 0 0 0 1px rgba(255,255,255,.7),0 1px 2px rgba(0,0,0,.08)}
.fam-kalkir .sec h2::after{content:"";display:block;width:64px;height:1px;margin:10px auto 0;background:linear-gradient(90deg,transparent,var(--gold),transparent)}
.fam-kalkir .sec,.fam-kalkir .sec p,.fam-kalkir .info b{color:var(--ink)}
.fam-kalkir .info,.fam-kalkir .info > div{border:0!important;background:none!important;box-shadow:none!important}
.fam-kalkir .info > div{border-bottom:1px solid color-mix(in srgb,var(--gold) 35%,transparent)!important;padding:14px 6px!important}
.fam-kalkir .info > div:last-child{border-bottom:0!important}
.fam-kalkir .info span{color:var(--accent);letter-spacing:.22em}
.fam-kalkir .count b{font-family:"Cormorant Garamond",serif;font-weight:500;color:var(--accent)}
.fam-kalkir .ibtn{border-radius:999px;color:var(--accent);background:transparent;border-color:color-mix(in srgb,var(--gold) 60%,transparent)}
.fam-kalkir input,.fam-kalkir select,.fam-kalkir textarea{background:#fff;color:var(--ink);border-color:color-mix(in srgb,var(--gold) 45%,transparent)}
.fam-kalkir .seg button{border-radius:999px!important;color:var(--ink)}
.fam-kalkir .seg button[aria-pressed="true"],.fam-kalkir button.submit{background:var(--accent)!important;color:var(--onacc)!important;border-color:var(--accent)!important;border-radius:999px;font-weight:600}
.fam-kalkir .dock{background:color-mix(in srgb,var(--sheet) 94%,transparent);color:var(--accent);backdrop-filter:blur(6px)}
.fam-kalkir .foot{color:var(--pagefg)}
.fam-kalkir .sec .rule{display:none}
@media (prefers-reduced-motion: reduce){.inv .klk-ccard,.inv .klk-env .klk-flap{transition:none}}
/* the flap's cut edges: a bright line with a faint shadow under it, so the vellum layers read */
.inv .klk-fedge{position:absolute;inset:0;width:100%;height:100%;overflow:visible}

/* ===== kampung (round 7): an antique print ===== */
.inv .kp-defs{position:absolute;width:0;height:0;overflow:hidden}
.inv .kp-board{position:absolute;inset:0;background:radial-gradient(ellipse 90% 70% at 40% 30%,rgba(255,255,255,.12),transparent 65%),radial-gradient(ellipse at 50% 50%,transparent 50%,rgba(0,0,0,.28)),url(/assets/linen.jpg) 0 0/200px,var(--ground);background-blend-mode:normal,normal,soft-light,normal}
/* the sheet of cotton paper */
.inv .kp-sheetw{position:relative;filter:drop-shadow(0 16px 18px rgba(0,0,0,.42)) drop-shadow(0 2px 3px rgba(0,0,0,.25))}
.inv .kp-sheet{position:relative;padding:11% 11% 9%;display:flex;flex-direction:column;align-items:center;text-align:center;color:var(--ink);
  background:radial-gradient(ellipse at 30% 20%,rgba(255,255,255,.35),transparent 60%),url(/assets/paper.jpg) 0 0/260px,var(--sheet);background-blend-mode:normal,multiply,normal;
  -webkit-mask:url(/assets/deckle.png) center/100% 100% no-repeat;mask:url(/assets/deckle.png) center/100% 100% no-repeat}
/* the plate: a slightly sunken field with the plate tone, the gravure, its etched lines and a little hand tint */
.inv .kp-plate{position:relative;display:block;width:100%;aspect-ratio:.9;padding:3.2%;border-radius:2px;
  background:color-mix(in srgb,var(--ink) 5%,transparent);
  box-shadow:inset 1px 1px 1.5px rgba(0,0,0,.16),inset -1px -1px 0 rgba(255,255,255,.6),1px 1px 0 rgba(255,255,255,.75),-1px -1px 0 rgba(0,0,0,.07)}
.inv .kp-plate.wide{aspect-ratio:1.62}
.inv .kp-plate > i{position:absolute;inset:3.2%}
.inv .kp-img{background:url(/assets/pc-pinang.jpg) 56% 50%/cover;filter:var(--kpfx) contrast(1.04)}
.inv .kp-lines{background:var(--ink);opacity:.32;-webkit-mask:url(/assets/sk-pinang.webp) 56% 50%/cover;mask:url(/assets/sk-pinang.webp) 56% 50%/cover}
.inv .kp-tint{mix-blend-mode:multiply;opacity:.55;
  background:radial-gradient(ellipse 70% 45% at 40% 18%,var(--wash1),transparent 70%),radial-gradient(ellipse 45% 25% at 30% 66%,var(--wash2),transparent 75%),radial-gradient(ellipse 60% 40% at 90% 70%,color-mix(in srgb,var(--wash2) 70%,#6a8a5a),transparent 75%)}
.inv .kp-cap{display:flex;justify-content:space-between;width:100%;margin-top:7px;font-family:"IM Fell English",serif;font-style:italic;font-size:10.5px;color:var(--ink);opacity:.7}
.inv .kp-title{font-family:"Pinyon Script",cursive;font-size:clamp(28px,9cqi,38px);line-height:1.1;margin-top:5%;color:var(--ink)}
.inv .kp-title span{font-family:"IM Fell English",serif;font-style:italic;font-size:.5em;color:var(--gold)}

/* cover */
.inv .cv-kampung2{background:var(--ground);overflow:hidden;transition:opacity .45s 1.05s}
.inv .kp-lift{position:absolute;left:9%;right:9%;top:10.5%;transform:rotate(-1.2deg);transition:transform 1.15s cubic-bezier(.55,0,.25,1) .1s}
.inv .kp-foot{position:absolute;left:0;right:0;bottom:6%;display:flex;flex-direction:column;align-items:center;gap:13px;color:var(--pagefg);text-align:center;transition:opacity .35s}
.inv .kp-to small{display:block;font-family:"IM Fell English SC",serif;font-size:11px;letter-spacing:.24em;opacity:.8}
.inv .kp-to b{font-family:"Pinyon Script",cursive;font-weight:400;font-size:26px;line-height:1.3}
.inv .kp-open{border:1px solid color-mix(in srgb,var(--pagefg) 45%,transparent);background:transparent;color:var(--pagefg);cursor:pointer;padding:12px 36px;border-radius:999px;
  font-family:"IM Fell English SC",serif;font-size:13px;letter-spacing:.24em}
.inv.opening .kp-foot{opacity:0}
.inv.opening .kp-lift{transform:translateY(-118%) rotate(-5deg)}
.inv.opening .cv-kampung2{opacity:0}

/* page: the print, titled */
.inv .pg-kampung2{background:var(--ground);color:var(--pagefg);padding:22px 16px 108px;gap:16px;overflow:hidden}
.inv .pg-kampung2 > :not(.kp-board){position:relative;z-index:2}
