.inv .pg-kipas > :not(.kipas-silk):not(.kipas-frame){position:relative;z-index:2}
.inv .pg-kipas .kipas-fan{position:relative;left:auto;bottom:auto;transform:none;width:min(94%,360px);cursor:default;margin-bottom:8px;transition:none}
.inv .pg-kipas .kipas-k{color:var(--pagefg)}
.inv .pg-kipas .names{color:var(--pagefg);font-size:clamp(44px,14cqi,58px)}
.inv .pg-kipas .names .amp{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.4em;color:var(--gold)}
.inv .kipas-venue{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:15px;opacity:.88}
/* skin: lace-edged silk cards, a fan over each heading */
.fam-kipas .scroller{background:var(--ground)}
.fam-kipas.cardsecs .sec{background:var(--sheet);margin-top:30px;box-shadow:0 0 0 1px color-mix(in srgb,var(--gold) 60%,transparent),0 0 0 5px var(--sheet),0 0 0 5.8px color-mix(in srgb,var(--gold) 40%,transparent),0 14px 24px rgba(0,0,0,.24)}
.fam-kipas.cardsecs .sec::after{content:"";position:absolute;left:-5px;right:-5px;top:-14px;height:9px;background:radial-gradient(circle at 50% 100%,var(--sheet) 4.5px,transparent 5px) 0 0/12px 9px repeat-x;pointer-events:none}
.fam-kipas .sec h2{display:flex;flex-direction:column;align-items:center;gap:8px;font-family:var(--d);letter-spacing:.26em}
.fam-kipas .sec h2::before{content:"";width:84px;height:47px;background:var(--kpfan) center/contain no-repeat;filter:drop-shadow(0 2px 2px rgba(0,0,0,.15))}
.fam-kipas .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .kipas-fan,.inv .kipas-rib,.inv .cv-kipas{transition:none}}

/* ===== kolam ===== */
.inv .klm-paint{position:absolute;inset:-4%;background:url(/assets/pd-monet.jpg) center/cover;animation:klDrift 40s ease-in-out infinite alternate}
.inv .klm-veil{position:absolute;inset:0;background:radial-gradient(ellipse 80% 60% at 50% 50%,transparent 40%,rgba(20,30,50,.28)),linear-gradient(180deg,rgba(255,255,255,.08),transparent 40%,rgba(20,30,50,.18))}
@keyframes klDrift{from{transform:scale(1.04) translate(0,0)}to{transform:scale(1.1) translate(-2%,1.5%)}}
/* the lace doily card */
.inv .klm-doily{position:relative;width:100%;aspect-ratio:200/190;filter:drop-shadow(0 8px 12px rgba(20,25,40,.3))}
.inv .klm-doily.big{aspect-ratio:200/280}
.inv .klm-doily.big .klm-txt{inset:11% 12%}
.inv .klm-lace{position:absolute;inset:-2%;width:104%;height:104%}
.inv .klm-txt{position:absolute;inset:16% 13%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--ink)}
.inv .klm-k{font-family:"Cormorant Garamond",serif;font-size:9px;letter-spacing:.34em;text-transform:uppercase;color:var(--accent)}
.inv .klm-names{font-family:"Pinyon Script",cursive;font-size:clamp(26px,8.6cqi,36px);line-height:1;margin:8px 0;display:flex;flex-direction:column;align-items:center}
.inv .klm-names span{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.45em;color:var(--gold);margin:2px 0}
.inv .klm-date{font-family:"Cormorant Garamond",serif;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--accent)}
.inv .klm-doily.big .klm-k{font-size:10.5px}
.inv .klm-doily.big .klm-names{font-size:clamp(42px,13cqi,54px);margin:14px 0}
.inv .klm-doily.big .klm-date{font-size:12px}
.inv .klm-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:15px;margin-top:8px}

/* cover */
.inv .cv-kolam{background:var(--ground);overflow:hidden;transition:opacity .4s 1.1s}
.inv .klm-to{position:absolute;top:11%;left:0;right:0;text-align:center;color:var(--pagefg);z-index:2;text-shadow:0 1px 12px rgba(10,20,40,.55);transition:opacity .4s}
.inv .klm-to small{display:block;font-family:"Cormorant Garamond",serif;font-size:10px;letter-spacing:.32em;text-transform:uppercase}
.inv .klm-to b{font-family:"Pinyon Script",cursive;font-weight:400;font-size:30px}
.inv .klm-stage{position:absolute;left:10%;right:10%;top:40%;aspect-ratio:1.42;z-index:3}
.inv .klm-env{position:absolute;inset:0;transition:transform .8s cubic-bezier(.5,0,.75,0) .35s}
.inv .klm-rear{z-index:1}.inv .klm-front{z-index:3;pointer-events:none}
.inv .klm-env > *{position:absolute}
.inv .klm-back{inset:0;background:linear-gradient(180deg,rgba(0,0,0,.18),rgba(0,0,0,.05)),url(/assets/paper.jpg) 0 0/200px,var(--env);background-blend-mode:normal,multiply,normal;border-radius:2px}
/* the open flap standing up behind, with a scalloped edge */
.inv .klm-flap{left:0;right:0;bottom:99%;height:56%;background:url(/assets/paper.jpg) 0 0/200px,var(--env);background-blend-mode:multiply;clip-path:polygon(0 100%,50% 0,100% 100%);filter:brightness(.94)}
.inv .klm-in{position:absolute;left:7%;right:7%;bottom:12%;z-index:2}
.inv .klm-pocket{inset:0;z-index:3;clip-path:polygon(0 0,50% 52%,100% 0,100% 100%,0 100%);border-radius:2px;
  background:linear-gradient(to top right,transparent 49.5%,rgba(0,0,0,.09) 50%,transparent 60%),linear-gradient(to top left,transparent 49.5%,rgba(255,255,255,.18) 50%,transparent 60%),url(/assets/paper.jpg) 0 0/200px,var(--env);background-blend-mode:normal,normal,multiply,normal;
  box-shadow:0 18px 30px -12px rgba(10,20,40,.5)}
.inv .klm-rear::after{content:"";position:absolute;inset:0;z-index:-1;box-shadow:0 26px 40px -14px rgba(10,20,40,.55);border-radius:2px}
.inv .klm-pearl{left:50%;top:52%;width:5.5%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-55%);z-index:4;
  background:radial-gradient(circle at 34% 30%,#fff 0 12%,#f3eee8 30%,#d9cfc6 62%,#b7aba2 100%);box-shadow:0 2px 3px rgba(0,0,0,.35)}
.inv .klm-open{position:absolute;left:50%;bottom:9%;transform:translateX(-50%);z-index:4;border:0;cursor:pointer;padding:15px 44px;border-radius:999px;background:rgba(255,255,255,.94);color:var(--accent);
  font-family:"Cormorant Garamond",serif;font-size:13px;font-weight:600;letter-spacing:.24em;text-transform:uppercase;box-shadow:0 8px 22px rgba(10,20,40,.3);white-space:nowrap;transition:opacity .35s}
/* opening: the envelope sinks away, the lace card rises and grows */
.inv.opening .klm-open,.inv.opening .klm-to{opacity:0}
.inv.opening .klm-env{transform:translateY(120cqh)}
.inv .klm-in{transition:transform 1s cubic-bezier(.3,.1,.2,1) .05s}
.inv.opening .klm-in{transform:translateY(-62%) scale(1.3)}
.inv.opening .cv-kolam{opacity:0}

/* page */
.inv .pg-kolam{background:var(--ground);padding:46px 34px 92px;gap:22px;overflow:hidden}
.inv .pg-kolam > .reveal{position:relative;z-index:2;width:100%;max-width:330px}
.inv .pg-kolam .klm-pill{position:relative;z-index:2;align-self:center;width:auto!important;flex:0 0 auto;padding:13px 38px;border-radius:999px;background:rgba(255,255,255,.94);color:var(--accent);text-decoration:none;
  font-family:"Cormorant Garamond",serif;font-size:12.5px;font-weight:600;letter-spacing:.24em;text-transform:uppercase;box-shadow:0 8px 22px rgba(10,20,40,.28)}

/* skin: lace-edged cards floating over the pond */
.fam-kolam .scroller{background:url(/assets/pd-monet.jpg) center/cover fixed,var(--ground)}
.fam-kolam.cardsecs .sec{background:color-mix(in srgb,var(--sheet) 93%,transparent);border-radius:4px;box-shadow:0 0 0 6px color-mix(in srgb,var(--sheet) 55%,transparent),0 14px 30px -8px rgba(10,20,40,.45);backdrop-filter:blur(3px)}
.fam-kolam .sec h2{font-family:"Pinyon Script",cursive;font-weight:400;text-transform:none;letter-spacing:0;font-size:34px;color:var(--accent)}
.fam-kolam .info,.fam-kolam .info > div{border:0!important;background:none!important}
.fam-kolam .info > div{border-bottom:1px dashed color-mix(in srgb,var(--accent) 35%,transparent)!important;padding:13px 6px!important}
.fam-kolam .info > div:last-child{border-bottom:0!important}
.fam-kolam .ibtn{border-radius:999px;border-color:color-mix(in srgb,var(--accent) 40%,transparent)}
.fam-kolam .dock{background:rgba(255,255,255,.9);backdrop-filter:blur(8px)}
.fam-kolam .foot{color:#fff;text-shadow:0 1px 6px rgba(0,0,0,.5)}
@media (prefers-reduced-motion: reduce){.inv .klm-paint{animation:none}.inv .klm-env,.inv .klm-in{transition:none}}

/* ===== komik (round 7): a two-colour graphic-novel panel on newsprint ===== */
/* newsprint: paper colour, fibre grain and a faint blue-grey show-through */
.inv .km-sheetin,.inv .km-leaf{background:url(/assets/paper.jpg) 0 0/260px,linear-gradient(180deg,rgba(255,255,255,.25),rgba(0,0,0,.03)),var(--paper);background-blend-mode:multiply,normal,normal;color:var(--ink)}
/* the printed panel: a flat second-colour tint, the art screened into ink dots, newsprint grain, an inked frame */
.inv .km-panel{position:relative;overflow:hidden;background:color-mix(in srgb,var(--spot) 34%,var(--paper));box-shadow:0 0 0 2px var(--ink);isolation:isolate}
.inv .km-dots{position:absolute;inset:0;background:var(--ink);-webkit-mask:linear-gradient(transparent,transparent) 50% 50%/cover no-repeat;mask:linear-gradient(transparent,transparent) 50% 50%/cover no-repeat}
.inv .km-grain{position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/220px;mix-blend-mode:multiply;opacity:.9}
/* caption boxes: hand-lettered caps on the flat second colour */
.inv .km-cap{font-family:"Kalam",cursive;font-weight:400;font-size:12.5px;line-height:1.25;letter-spacing:.06em;text-transform:uppercase;color:var(--ink);text-align:left;
  background:url(/assets/paper.jpg) 0 0/200px,color-mix(in srgb,var(--spot) 55%,var(--paper));background-blend-mode:multiply;box-shadow:0 0 0 1.5px var(--ink);padding:6px 9px 5px}
.inv .km-cap small{display:block;font-weight:300;font-size:9.5px;letter-spacing:.14em;opacity:.8}
.inv .km-head{display:flex;justify-content:space-between;font-family:"Kalam",cursive;font-weight:400;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--ink);opacity:.8}
.inv .km-more{font-family:"Kalam",cursive;font-weight:300;font-size:13px;letter-spacing:.04em;color:var(--ink);text-align:right}

/* cover */
.inv .cv-komik2{background:transparent;overflow:hidden;perspective:1600px}
.inv .km-desk{position:absolute;inset:0;background:radial-gradient(ellipse 80% 60% at 50% 38%,rgba(255,255,255,.1),transparent 70%),url(/assets/paper.jpg) 0 0/300px,var(--ground);background-blend-mode:normal,multiply,normal;transition:opacity .6s .75s}
.inv .km-sheet{position:absolute;left:7.5%;right:7.5%;top:8.5%;z-index:2;transform-origin:0 50%;transform-style:preserve-3d;
  transition:transform 1.3s cubic-bezier(.55,0,.3,1) .1s,opacity .3s 1.1s;filter:drop-shadow(0 18px 18px rgba(20,15,10,.32)) drop-shadow(0 2px 3px rgba(20,15,10,.25))}
.inv .km-sheetin{padding:16px 16px 14px;display:flex;flex-direction:column;gap:12px}
.inv .km-sheet .km-panel{aspect-ratio:1/1.04}
.inv .km-c1{position:absolute;left:10px;top:10px;z-index:3}
.inv .km-cn{font-family:"Cormorant Garamond",serif;font-style:italic;font-weight:500;font-size:clamp(28px,8.6cqi,36px);line-height:1.05;text-align:center;color:var(--ink);margin-top:2px}
.inv .km-cn span{color:color-mix(in srgb,var(--spot) 80%,var(--ink));font-weight:400}
.inv .km-sheet .km-more{margin-top:-6px}
/* the page catching the light as it turns */
.inv .km-turn{position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.18),transparent 30%,rgba(255,255,255,.2));opacity:0;transition:opacity 1.3s;pointer-events:none}
.inv .km-foot{position:absolute;left:0;right:0;bottom:5.5%;z-index:3;display:flex;flex-direction:column;align-items:center;gap:12px;color:var(--pagefg);transition:opacity .35s}
.inv .km-to{text-align:center}
.inv .km-to small{display:block;font-family:"Kalam",cursive;font-size:10px;letter-spacing:.24em;text-transform:uppercase;opacity:.75}
.inv .km-to b{font-family:"Cormorant Garamond",serif;font-style:italic;font-weight:500;font-size:21px}
.inv .km-open{border:1.5px solid var(--pagefg);background:transparent;color:var(--pagefg);cursor:pointer;padding:12px 36px 11px;border-radius:999px;
  font-family:"Kalam",cursive;font-weight:400;font-size:13px;letter-spacing:.22em;text-transform:uppercase}
/* opening: the leaf turns over to the left */
.inv.opening .km-sheet{transform:rotateY(-112deg);opacity:0}
.inv.opening .km-turn{opacity:1}
.inv.opening .km-foot{opacity:0}
.inv.opening .km-desk{opacity:0}

/* page: the title page of chapter one */
.inv .pg-komik2{background:var(--ground);padding:14px 14px 100px;justify-content:flex-start}
.inv .km-leaf{position:relative;width:100%;flex:1;display:flex;flex-direction:column;align-items:center;gap:11px;padding:44px 18px 16px;box-shadow:0 14px 26px -10px rgba(20,15,10,.35),0 1px 2px rgba(20,15,10,.2)}
.inv .km-leaf .km-head{width:100%}
.inv .km-k{font-family:"Kalam",cursive;font-weight:400;font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--ink);margin-top:4px}
.inv .km-names{font-family:"Cormorant Garamond",serif;font-style:italic;font-weight:500;font-size:clamp(34px,10.4cqi,44px);line-height:.98;color:var(--ink);display:flex;flex-direction:column;align-items:center}
.inv .km-names span{font-size:.6em;color:color-mix(in srgb,var(--spot) 80%,var(--ink));margin:2px 0}
.inv .km-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:12px;width:100%;align-items:stretch}
.inv .km-panel.tall{aspect-ratio:1/1.22}
.inv .km-stack{display:flex;flex-direction:column;gap:9px;justify-content:center}
.inv .km-stack .km-cap{background:url(/assets/paper.jpg) 0 0/200px,var(--paper);background-blend-mode:multiply;font-size:12px;text-transform:none;letter-spacing:.02em}
.inv .km-stack .km-cap small{text-transform:uppercase}
.inv .km-stack .km-cap:nth-child(2){background:url(/assets/paper.jpg) 0 0/200px,color-mix(in srgb,var(--spot) 55%,var(--paper))}
.inv .km-tiles{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;width:100%;margin-bottom:6px}
.inv .km-tile{flex:0 0 auto;white-space:nowrap;font-family:"Kalam",cursive;font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;text-decoration:none;color:var(--ink);padding:7px 12px 6px;border-radius:999px;box-shadow:inset 0 0 0 1.5px var(--ink)}
.inv .km-tile i{font-style:normal;color:color-mix(in srgb,var(--spot) 80%,var(--ink))}
.inv .km-stack .km-more{font-size:12px;margin-top:2px}

/* skin: newsprint panels with an inked frame; headings are caption boxes */
.fam-komik .scroller{background:url(/assets/paper.jpg) 0 0/300px,var(--ground);background-blend-mode:multiply}
.fam-komik.cardsecs .sec{background:url(/assets/paper.jpg) 0 0/260px,var(--paper);background-blend-mode:multiply;color:var(--ink);border-radius:0;
  box-shadow:inset 0 0 0 2px var(--ink),inset 0 0 0 6px var(--paper),0 12px 22px -10px rgba(20,15,10,.35)}
.fam-komik .sec h2{display:table;margin-left:auto;margin-right:auto;font-family:"Kalam",cursive;font-weight:400;font-size:15px;letter-spacing:.2em;text-transform:uppercase;color:var(--ink);
  background:color-mix(in srgb,var(--spot) 55%,var(--paper));box-shadow:0 0 0 1.5px var(--ink);padding:7px 14px 5px}
.fam-komik .sec,.fam-komik .sec p,.fam-komik .info b{color:var(--ink)}
.fam-komik .info,.fam-komik .info > div{border:0!important;background:none!important}
.fam-komik .info > div{border-bottom:1px solid color-mix(in srgb,var(--ink) 22%,transparent)!important;padding:13px 6px!important}
.fam-komik .info > div:last-child{border-bottom:0!important}
.fam-komik .info span,.fam-komik .timeline b,.fam-komik form label{font-family:"Kalam",cursive;letter-spacing:.16em;color:color-mix(in srgb,var(--ink) 75%,var(--spot))}
