@media (prefers-reduced-motion: reduce){.inv .km-sheet,.inv .km-desk{transition:none}}

/* ===== konservatori (Rumah Kaca): a garden painting on an arched card under a glazed vellum jacket ===== */
.inv .cv-konservatori,.inv .pg-konservatori{background:var(--ground)}
.inv .rkc-ground{position:absolute;inset:0;pointer-events:none;background:radial-gradient(80% 55% at 50% 40%,rgba(255,255,255,.35),transparent 70%),var(--ground)}
.inv .rkc-ground::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/360px;mix-blend-mode:multiply;opacity:.55}
.inv .pg-konservatori .rkc-ground{position:fixed}
.inv .rkc-paint{position:absolute;inset:0;border-radius:inherit;background:var(--art) var(--ap)/cover no-repeat}
