.inv .rkc-sm{font-family:"Cormorant Garamond",serif;font-size:14px;color:var(--ink);opacity:.8;margin:0}
.inv .rkc-bis{font-family:"Amiri",serif;font-size:18px;color:var(--accent);margin:0}

