.inv .rkc-glz circle,.inv .rkc-glz .rkc-fl{fill:#fff;stroke:none}

/* ---------- cover ---------- */
.inv .cv-konservatori{overflow:hidden;transition:opacity .45s 1.15s}
.inv .rkc-card{position:absolute;left:8%;right:8%;top:4%;bottom:8%;border-radius:50% 50% 4px 4px/24% 24% 4px 4px;perspective:1400px;
  box-shadow:0 0 0 1.5px rgba(255,255,255,.7),0 0 0 4px var(--edge),0 0 0 4.6px rgba(0,0,0,.08),0 26px 40px -16px rgba(30,30,40,.45),0 4px 10px rgba(30,30,40,.14);transition:transform 1.2s cubic-bezier(.4,0,.2,1) .3s}
.inv .rkc-vel{position:absolute;left:0;right:0;top:0;height:86%;border-radius:50% 50% 0 0/27.9% 27.9% 0 0;transform-origin:50% 0;
