.fam-lili.cardsecs .sec{background:radial-gradient(ellipse at 50% 0,color-mix(in srgb,var(--sheet) 80%,#fff 6%),var(--sheet) 70%);color:var(--ink);border-radius:3px;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--gold) 55%,transparent),0 16px 30px -10px rgba(0,0,0,.65)}
.fam-lili .sec h2{font-family:"Bodoni Moda",serif;font-style:italic;font-weight:400;text-transform:none;letter-spacing:.01em;font-size:30px;color:var(--accent);line-height:1.15}
.fam-lili .sec,.fam-lili .sec p,.fam-lili .info b{color:var(--ink)}
.fam-lili .info,.fam-lili .info > div{border:0!important;background:none!important;box-shadow:none!important}
.fam-lili .info > div{border-bottom:1px solid color-mix(in srgb,var(--gold) 30%,transparent)!important;padding:13px 6px!important}
.fam-lili .info > div:last-child{border-bottom:0!important}
.fam-lili .info span{color:var(--accent);letter-spacing:.22em}
.fam-lili .ibtn{color:var(--accent);border-color:color-mix(in srgb,var(--gold) 60%,transparent);border-radius:999px;background:transparent}
.fam-lili .count b{color:var(--accent)}
.fam-lili input,.fam-lili select,.fam-lili textarea{background:rgba(255,255,255,.07)!important;color:var(--ink)!important;border-color:color-mix(in srgb,var(--gold) 50%,transparent)!important}
.fam-lili input::placeholder,.fam-lili textarea::placeholder{color:color-mix(in srgb,var(--ink) 55%,transparent)}
.fam-lili select option{background:var(--sheet);color:var(--ink)}
.fam-lili .seg button{color:var(--ink);border-color:color-mix(in srgb,var(--gold) 50%,transparent)}
.fam-lili .seg button[aria-pressed="true"],.fam-lili button.submit{font-weight:700;color:var(--ground)!important;background:var(--accent)!important;border-color:var(--accent)!important}
