.fam-lili.ll-light .scroller::before{opacity:.18}
.fam-lili.ll-light.cardsecs .sec{background:var(--sheet);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--gold) 55%,transparent),0 14px 28px -14px rgba(60,30,30,.35)}
.fam-lili.ll-light input,.fam-lili.ll-light select,.fam-lili.ll-light textarea{background:#fff!important}
.fam-lili.ll-light .seg button[aria-pressed="true"],.fam-lili.ll-light button.submit{color:var(--sheet)!important}
.fam-lili.ll-light .dock{background:color-mix(in srgb,var(--sheet) 94%,transparent)}
@media (prefers-reduced-motion: reduce){.inv .cv-lili .ll-fl,.inv .ll-mid{transition:none}}
.inv .pg-lili .ll-mono{width:112px;height:112px}
.inv .pg-lili .ll-ini{font-size:42px}
.inv .pg-lili .ll-ini.jw{font-size:34px}

/* ===== lilin (Cahaya Lilin): a sealed tall envelope on linen by candlelight ===== */
.inv .cv-lilin,.inv .pg-lilin{background:var(--table);color:var(--pagefg)}
/* the cloth: linen weave, a vignette into the dark */
.inv .lln-cloth{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse 110% 80% at 78% 16%,transparent 30%,rgba(0,0,0,.62) 100%)}
.inv .lln-cloth::before{content:"";position:absolute;inset:0;background:url(/assets/linen.jpg) 0 0/190px;mix-blend-mode:soft-light;opacity:.75}
.inv .lln-light .lln-cloth{background:radial-gradient(ellipse 110% 80% at 78% 16%,transparent 40%,rgba(90,60,30,.22) 100%)}
.inv .lln-light .lln-cloth::before{mix-blend-mode:multiply;opacity:.3}
/* the candle is just out of the picture, top left: a warm pool of light that breathes very slowly */
.inv .lln-glow{position:absolute;inset:0;pointer-events:none;mix-blend-mode:screen;
  background:radial-gradient(circle at 88% 6%,rgba(255,246,220,.5),rgba(var(--glow),.3) 7%,rgba(var(--glow),.12) 30%,transparent 64%),radial-gradient(ellipse 80% 55% at 62% 26%,rgba(var(--glow),.12),transparent 70%);
  animation:llnBreathe 7s ease-in-out infinite alternate}
.inv .lln-light .lln-glow{mix-blend-mode:soft-light;opacity:.9}
/* the taper: translucent wax lit from inside near the flame, slightly out of focus */
.inv .lln-candle{position:absolute;right:7%;top:6.5%;width:7%;height:46%;z-index:1;pointer-events:none;filter:blur(.7px)}
.inv .lln-wax{position:absolute;left:0;right:0;top:0;bottom:0;border-radius:45% 45% 0 0/5px 5px 0 0;
  background:linear-gradient(180deg,rgba(255,236,190,.55),transparent 22%),linear-gradient(90deg,#8a7a62,#efe2c6 30%,#fff6e2 48%,#d9c8a6 72%,#6a5a44);
  -webkit-mask:linear-gradient(180deg,#000 50%,transparent);mask:linear-gradient(180deg,#000 50%,transparent)}
.inv .lln-light .lln-wax{-webkit-mask:linear-gradient(180deg,#000 60%,rgba(0,0,0,.4));mask:linear-gradient(180deg,#000 60%,rgba(0,0,0,.4))}
.inv .lln-wax::before{content:"";position:absolute;left:12%;right:12%;top:-1px;height:6px;border-radius:50%;background:radial-gradient(ellipse at 50% 40%,#fff8e0,#e8d4a8 70%,#b8a07a)}
.inv .lln-drip{position:absolute;right:8%;top:1px;width:24%;height:18%;border-radius:0 0 50% 50%/0 0 12px 12px;background:linear-gradient(90deg,#e8d8b8,#fff6e4 50%,#d8c49e);box-shadow:1px 1px 1px rgba(0,0,0,.2)}
.inv .lln-wick{position:absolute;left:50%;top:-9px;width:1.6px;height:10px;margin-left:-.8px;background:linear-gradient(#111,#3a2a1a);border-radius:1px;transform:rotate(4deg)}
.inv .lln-flame{position:absolute;left:50%;top:-44px;width:15px;height:38px;margin-left:-7.5px;border-radius:50% 50% 50% 50%/62% 62% 38% 38%;
  background:radial-gradient(ellipse 40% 30% at 50% 82%,rgba(90,120,255,.55),transparent),radial-gradient(ellipse 50% 55% at 50% 66%,#fff 30%,#fff1c0 55%,#ffb347 80%,rgba(230,110,30,0) 100%);
  box-shadow:0 0 18px 6px rgba(255,190,100,.45),0 0 60px 26px rgba(var(--glow),.22);transform-origin:50% 90%;animation:llnFlame 7s ease-in-out infinite alternate}
@keyframes llnFlame{0%{transform:scaleY(1) rotate(-1deg)}40%{transform:scaleY(1.06) rotate(1.5deg)}70%{transform:scaleY(.97) rotate(0)}100%{transform:scaleY(1.03) rotate(-1.5deg)}}
@keyframes llnBreathe{0%{opacity:.86}45%{opacity:1}70%{opacity:.92}100%{opacity:.98}}

/* copperplate names; foil on dark paper, ink on light paper */
.inv .lln-names{font-family:"Pinyon Script",cursive;font-weight:400;line-height:.98;margin:0;display:flex;flex-direction:column;align-items:center}
.inv .lln-names em{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.36em;line-height:1.4;margin:.05em 0}
.inv .lln-print .lln-names,.inv .lln-print .lln-k,.inv .lln-print .lln-cd{background:url(/assets/foil.jpg) 0 0/150px,linear-gradient(170deg,color-mix(in srgb,var(--envink) 60%,#fff),var(--envink) 40%,var(--gold) 75%,color-mix(in srgb,var(--envink) 70%,#fff));
  background-blend-mode:overlay;-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 1px 0 rgba(0,0,0,.45))}
.inv .lln-light .lln-print .lln-names,.inv .lln-light .lln-print .lln-k,.inv .lln-light .lln-print .lln-cd{background:none;color:var(--envink);filter:none;text-shadow:0 1px 0 rgba(255,255,255,.6),0 -.5px 0 rgba(0,0,0,.18)}
.inv .lln-k{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:9.5px;letter-spacing:.42em;padding-left:.42em;text-transform:uppercase;margin:0}

/* the envelope, tall and narrow, back up */
.inv .lln-env{position:absolute;z-index:2;left:12%;width:63%;top:6.5%;aspect-ratio:1/1.74;transform:rotate(-3.5deg);perspective:1100px;
  filter:drop-shadow(-12px 22px 18px rgba(0,0,0,.55)) drop-shadow(-2px 4px 3px rgba(0,0,0,.4))}
.inv .lln-light .lln-env{filter:drop-shadow(-12px 20px 18px rgba(90,60,30,.32)) drop-shadow(-2px 3px 3px rgba(90,60,30,.25))}
.inv .lln-env > *{position:absolute}
.inv .lln-back{inset:0;border-radius:3px;background:color-mix(in srgb,var(--env) 70%,#000);overflow:hidden}
/* a painted liner (Ruysch) glued inside, set in from the edges */
.inv .lln-liner{position:absolute;left:6%;right:6%;top:3%;height:38%;background:var(--lin) 50% 38%/170% auto;clip-path:polygon(0 0,100% 0,50% 78%);filter:brightness(.8)}
.inv .lln-card{left:7%;right:7%;top:4%;height:72%;z-index:1;display:flex;flex-direction:column;align-items:center;padding-top:16%;gap:10px;text-align:center;color:var(--accent);
  background:url(/assets/paper.jpg) 0 0/220px,var(--sheet);background-blend-mode:multiply;box-shadow:0 -2px 8px rgba(0,0,0,.25);transition:transform .75s cubic-bezier(.3,.1,.2,1) .75s}
.inv .lln-card .lln-ck{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:8.5px;letter-spacing:.36em;text-transform:uppercase;margin:0;color:var(--ink)}
.inv .lln-card .lln-names{font-size:clamp(28px,9cqi,36px)}
.inv .lln-pocket{inset:0;z-index:2;border-radius:3px;clip-path:polygon(0 0,50% 24%,100% 0,100% 100%,0 100%);
  background:linear-gradient(180deg,rgba(255,255,255,.08),transparent 40%,rgba(0,0,0,.18)),var(--env)}
.inv .lln-pocket::before{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/220px;mix-blend-mode:overlay;opacity:.4}
.inv .lln-light .lln-pocket::before{mix-blend-mode:multiply;opacity:.55}
/* the folds: two side flaps meeting the bottom flap, a crease that catches the light */
.inv .lln-pocket::after{content:"";position:absolute;inset:0;background:
  linear-gradient(to top right,transparent calc(50% - .6px),rgba(0,0,0,.32) 50%,rgba(255,255,255,.14) calc(50% + 1px),transparent calc(50% + 2px)) 0 100%/50.2% 40% no-repeat,
  linear-gradient(to top left,transparent calc(50% - .6px),rgba(0,0,0,.32) 50%,rgba(255,255,255,.14) calc(50% + 1px),transparent calc(50% + 2px)) 100% 100%/50.2% 40% no-repeat,
  linear-gradient(to bottom right,transparent 49.5%,rgba(0,0,0,.08) 50%,transparent 70%) 0 0/50% 100% no-repeat}
.inv .lln-flap{left:0;right:0;top:0;height:42%;z-index:4;transform-origin:50% 0;transform-style:preserve-3d;transition:transform .7s cubic-bezier(.45,0,.25,1) .4s,z-index 0s .75s}
.inv .lln-flapface,.inv .lln-flapin{position:absolute;inset:0;clip-path:polygon(0 0,100% 0,52% 98%,50% 100%,48% 98%);-webkit-backface-visibility:hidden;backface-visibility:hidden}
.inv .lln-flapface{background:linear-gradient(176deg,rgba(255,255,255,.12),transparent 50%,rgba(0,0,0,.12)),var(--env);filter:drop-shadow(0 3px 3px rgba(0,0,0,.35))}
.inv .lln-flapface::before{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 30px 0/220px;mix-blend-mode:overlay;opacity:.4}
.inv .lln-light .lln-flapface::before{mix-blend-mode:multiply;opacity:.55}
/* the deckled edge of the flap, a deeper line just inside it */
.inv .lln-flapface::after{content:"";position:absolute;inset:0;background:linear-gradient(to top right,transparent calc(50% + 4px),color-mix(in srgb,var(--gold) 85%,transparent) calc(50% + 4.6px),transparent calc(50% + 5.6px)) 0 0/50% 100% no-repeat,linear-gradient(to top left,transparent calc(50% + 4px),color-mix(in srgb,var(--gold) 85%,transparent) calc(50% + 4.6px),transparent calc(50% + 5.6px)) 100% 0/50% 100% no-repeat}
.inv .lln-flapin{transform:rotateX(180deg);background:color-mix(in srgb,var(--env) 85%,#000)}
.inv .lln-flapin::after{content:"";position:absolute;left:5%;right:5%;top:0;bottom:7%;background:var(--lin) 50% 30%/150% auto;clip-path:polygon(0 0,100% 0,50% 100%);filter:brightness(.85)}
/* the print on the envelope's body, under the seal */
.inv .lln-print{left:5%;right:5%;top:56.5%;bottom:4%;z-index:3;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:8px;pointer-events:none}
.inv .lln-print .lln-names{font-size:clamp(36px,11.8cqi,46px)}
.inv .lln-cd{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:12px;letter-spacing:.32em;padding-left:.32em;margin:2px 0 0}

/* the wax seal, which cracks in two */
.inv .lln-seal{position:absolute;display:block;aspect-ratio:1}
.inv .lln-seal.lcs{left:50%;top:42%;width:34%;transform:translate(-50%,-50%) rotate(6deg);z-index:6}
.inv .lln-half{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--seal) center/contain no-repeat;
  filter:drop-shadow(0 4px 4px rgba(0,0,0,.45));transition:transform .6s cubic-bezier(.4,0,.3,1) .12s,opacity .45s .45s}
.inv .lln-half span{font-family:"Pinyon Script",cursive;font-size:clamp(22px,7.4cqi,30px);line-height:1;color:rgba(0,0,0,.42);text-shadow:0 1px 0 rgba(255,255,255,.4),0 -1px 0 rgba(0,0,0,.35);white-space:nowrap}
.inv .lln-half span i{font-style:normal;font-family:"Cormorant Garamond",serif;font-size:.5em;margin:0 2px}
.inv .lln-half .jw{font-family:"Aref Ruqaa","Amiri",serif;font-size:clamp(20px,6.4cqi,26px)}

/* the ribbon's tail and the tag on it */
.inv .lln-tail{position:absolute;inset:0;width:100%;height:100%;z-index:1;pointer-events:none;overflow:visible;transition:opacity .4s}
.inv .lln-tag{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center;border:0;color:var(--ink);cursor:pointer;
  background:url(/assets/paper.jpg) 0 0/200px,var(--sheet);background-blend-mode:multiply;
  clip-path:polygon(16% 0,84% 0,100% 13%,100% 100%,0 100%,0 13%);filter:drop-shadow(-4px 8px 7px rgba(0,0,0,.5))}
.inv .lln-light .lln-tag{filter:drop-shadow(4px 8px 7px rgba(90,60,30,.3))}
.inv .lln-tag::before{content:"";position:absolute;inset:7px;border:.6px solid color-mix(in srgb,var(--accent) 45%,transparent);clip-path:polygon(15% 0,85% 0,100% 12%,100% 100%,0 100%,0 12%);pointer-events:none}
/* the eyelet, a brass ring round the punched hole */
.inv .lln-eye{position:absolute;left:50%;top:7%;width:15px;height:15px;transform:translateX(-50%);border-radius:50%;
  background:radial-gradient(circle,var(--table) 3.4px,#7a5a26 3.9px,#f0d9a0 5px,#a07a36 6.2px,#5a3c12 7px,transparent 7.4px)}
.inv .lln-tag small{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:8.5px;letter-spacing:.24em;text-transform:uppercase;color:var(--accent);max-width:90%}
.inv .lln-tag b{font-family:"Pinyon Script",cursive;font-weight:400;font-size:25px;line-height:1.05;max-width:94%;overflow-wrap:anywhere}
.inv .lln-go{margin-top:6px;font-family:"Cormorant Garamond",serif;font-weight:700;font-size:10px;letter-spacing:.26em;text-transform:uppercase;color:var(--sheet);background:var(--accent);padding:8px 14px;border-radius:999px}
.inv .lln-tag.lct{z-index:3;left:49%;top:70%;width:44%;padding:34px 8px 16px;transform:rotate(8deg);transition:opacity .35s,transform .6s}
/* a rose from the painting, lying on the cloth (its own dark ground melts into the night) */
.inv .lln-rose{position:absolute;left:-10%;bottom:4%;width:56%;aspect-ratio:1.25;pointer-events:none;mix-blend-mode:lighten;background-repeat:no-repeat;background-size:380% auto;background-position:22.9% 94.7%;
  transform:rotate(-24deg);filter:brightness(.85) saturate(1.05);-webkit-mask:radial-gradient(ellipse 50% 50%,#000 46%,transparent 92%);mask:radial-gradient(ellipse 50% 50%,#000 46%,transparent 92%)}
.inv .lln-pressed{position:absolute;left:-14%;bottom:3%;width:52%;height:auto;pointer-events:none;transform:rotate(-30deg);filter:sepia(.3) drop-shadow(3px 6px 5px rgba(90,60,30,.3));opacity:.95}

/* cover */
.inv .cv-lilin{overflow:hidden;transition:opacity .45s 1.15s}
/* opening: the tag drops away, the seal cracks, the flap opens on the liner, the card rises */
.inv.opening .lln-tag.lct{opacity:0;transform:rotate(14deg) translateY(10%)}
.inv.opening .lln-tail{opacity:0}
.inv.opening .lln-seal.lcs .h0{transform:translate(-26%,10%) rotate(-24deg);opacity:0}
.inv.opening .lln-seal.lcs .h1{transform:translate(26%,14%) rotate(20deg);opacity:0}
.inv.opening .lln-flap{transform:rotateX(180deg);z-index:0}
.inv.opening .lln-card{transform:translateY(-62%)}
.inv.opening .lln-print{opacity:0;transition:opacity .3s .2s}
.inv.opening .cv-lilin{opacity:0}

/* page: the card out on the cloth */
.inv .pg-lilin{padding:40px 0 96px;overflow:hidden}
.inv .lln-penv{position:absolute;right:-22%;top:-3%;width:70%;aspect-ratio:1/1.74;transform:rotate(24deg);filter:drop-shadow(10px 18px 16px rgba(0,0,0,.5));opacity:.95}
.inv .lln-penv > *{position:absolute}
.inv .lln-penv .lln-liner{height:46%}
.inv .lln-light .lln-penv{filter:drop-shadow(10px 18px 16px rgba(90,60,30,.3))}
.inv .pg-lilin .lln-rose{left:-16%;bottom:auto;top:-4%;transform:rotate(150deg)}
.inv .pg-lilin .lln-pressed{left:-18%;bottom:auto;top:-2%;transform:rotate(160deg)}
.inv .lln-letter{position:relative;z-index:2;width:80%;max-width:330px;transform:rotate(-1.5deg);padding:10px;
  background:url(/assets/paper.jpg) 0 0/240px,var(--sheet);background-blend-mode:multiply;
  -webkit-mask:url(/assets/deckle.png) center/100% 100% no-repeat;mask:url(/assets/deckle.png) center/100% 100% no-repeat;filter:drop-shadow(8px 14px 14px rgba(0,0,0,.45))}
.inv .lln-light .lln-letter{filter:drop-shadow(8px 14px 14px rgba(90,60,30,.28))}
/* letterpress: the type bitten into soft cotton */
.inv .lln-lin{display:flex;flex-direction:column;align-items:center;text-align:center;padding:34px 16px 30px;color:var(--ink);
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 35%,transparent),inset 0 0 0 5px transparent,inset 0 0 0 5.6px color-mix(in srgb,var(--accent) 22%,transparent)}
.inv .lln-lin .lln-k{color:var(--accent);text-shadow:0 1px 0 rgba(255,255,255,.7)}
.inv .lln-lin .lln-names{font-size:clamp(42px,13.4cqi,56px);color:var(--accent);margin:12px 0 6px;text-shadow:0 1px 0 rgba(255,255,255,.7),0 -.5px 0 rgba(0,0,0,.2)}
.inv .lln-lin .lln-names em{color:var(--ink);opacity:.75}
.inv .lln-rule{display:flex;align-items:center;gap:8px;width:120px;margin:6px 0 10px}
.inv .lln-rule::before,.inv .lln-rule::after{content:"";flex:1;height:.8px;background:color-mix(in srgb,var(--accent) 55%,transparent)}
.inv .lln-rule b{width:7px;height:9px;border-radius:50% 50% 50% 50%/60% 60% 40% 40%;background:#8a1f24;box-shadow:inset -1px -1px 2px rgba(0,0,0,.4),inset 1px 1px 1px rgba(255,255,255,.3)}
.inv .lln-date{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:12px;letter-spacing:.24em;text-transform:uppercase;margin:0;color:var(--ink)}
.inv .lln-hj{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:14px;opacity:.75;margin:4px 0 0}
.inv .lln-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:18px;margin:10px 0 0;max-width:24ch;line-height:1.25}
.inv .lln-bis{font-family:"Amiri",serif;font-size:17px;margin:0 0 10px;color:var(--accent)}
.inv .pg-lilin .couple-ph.front{width:min(42%,140px);margin:0 auto 16px;box-shadow:0 0 0 6px var(--sheet),0 0 0 6.6px color-mix(in srgb,var(--accent) 40%,transparent),0 4px 10px rgba(0,0,0,.2)}
.inv .lln-seal.lps{z-index:3;left:5%;top:auto;bottom:13%;width:22%}
.inv .lln-seal.lps .h0{transform:translate(-14%,4%) rotate(-28deg)}
.inv .lln-seal.lps .h1{transform:translate(18%,-6%) rotate(16deg)}
.inv .lln-tag.lpt{position:relative;z-index:3;margin:-18px -34% 0 0;width:46%;padding:30px 8px 16px;gap:0;cursor:default;transform:rotate(-6deg)}
.inv .lln-tag.lpt a{font-family:"Pinyon Script",cursive;font-size:22px;color:var(--accent);text-decoration:none;line-height:1.35;padding:1px 6px}
.inv .lln-tag.lpt a + a{border-top:.6px solid color-mix(in srgb,var(--accent) 30%,transparent)}

/* skin: deckled cotton cards in the candlelight */
.fam-lilin .scroller{background:radial-gradient(circle at 0 0,rgba(var(--glow),.22),transparent 55%) fixed,var(--table)}
.fam-lilin .scroller::before{content:"";position:fixed;inset:0;pointer-events:none;background:url(/assets/linen.jpg) 0 0/190px;mix-blend-mode:soft-light;opacity:.6}
.fam-lilin.lln-light .scroller::before{mix-blend-mode:multiply;opacity:.25}
.fam-lilin.cardsecs .sec{color:var(--ink);padding-top:40px;padding-bottom:40px;background:url(/assets/paper.jpg) 0 0/240px,var(--sheet);background-blend-mode:multiply;border-radius:0;
