.inv .mc-side::after{content:"";position:absolute;inset:6% 22%;background:repeating-linear-gradient(172deg,transparent 0 22px,rgba(0,0,0,.28) 22px 23px,transparent 23px 41px,rgba(255,240,220,.08) 41px 42px)}
/* the tray: floor, two walls and the end that shows at the open top of the sleeve */
.inv .mc-tray{inset:0;transform-style:preserve-3d;transition:transform 1.15s cubic-bezier(.45,.05,.25,1) .1s}
