.inv .mc-tw.l{left:calc(3% - (var(--d) - 3px) / 2);transform:rotateY(90deg)}
.inv .mc-tw.r{right:calc(3% - (var(--d) - 3px) / 2);transform:rotateY(-90deg)}
.inv .mc-te{left:3%;right:3%;top:calc((var(--d) - 3px) / -2 + .5%);height:calc(var(--d) - 3px);transform:rotateX(90deg);
  background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(0,0,0,.08)),url(/assets/paper.jpg) 0 0/160px,var(--board);background-blend-mode:normal,multiply,normal;box-shadow:inset 0 0 0 1px rgba(0,0,0,.12)}
.inv .mc-note{position:absolute;left:12%;right:12%;top:7%;padding:10px 8px 12px;text-align:center;background:var(--sheet) url(/assets/paper.jpg) 0 0/160px;background-blend-mode:multiply;
