.inv .mh-leath::after{content:"";position:absolute;inset:0;background:url(/assets/velvet.jpg) 0 0/180px;mix-blend-mode:soft-light;opacity:.6}
/* the vellum leaf */
.inv .mh-leaf{position:relative;width:100%;padding:9% 8.5% 11%;background:var(--sheet) url(/assets/paper.jpg) 0 0/260px;background-blend-mode:multiply;border-radius:1px;
  box-shadow:inset 0 0 34px rgba(150,110,50,.28),inset 0 0 3px rgba(120,90,40,.3),0 1px 1px rgba(0,0,0,.25),0 18px 30px -10px rgba(0,0,0,.55),0 4px 10px rgba(0,0,0,.25)}
.inv .mh-block{position:relative;width:100%;aspect-ratio:100/150}
.inv .mh-arch{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.inv .mh-arch .mh-in{stroke:var(--accent)}
.inv .mh-txt{position:absolute;left:18%;right:18%;top:23%;bottom:8%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--ink)}
.inv .mh-k{font-family:"Cormorant Garamond",serif;font-size:8.5px;letter-spacing:.3em;text-transform:uppercase;color:var(--accent);line-height:1.5}
.inv .mh-names{font-family:"Pinyon Script",cursive;font-size:clamp(28px,9cqi,36px);line-height:1.02;margin:10px 0 10px;display:flex;flex-direction:column;align-items:center;color:var(--ink);overflow-wrap:anywhere}
.inv .mh-names span{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:.42em;margin:3px 0;
  background:url(/assets/foil.jpg) 0 0/120px,linear-gradient(#d9b46a,#9a7334);background-blend-mode:overlay;-webkit-background-clip:text;background-clip:text;color:transparent}
.inv .mh-date{font-family:"Cormorant Garamond",serif;font-size:9.5px;letter-spacing:.26em;text-transform:uppercase;color:var(--accent)}
.inv .mh-hj{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:13px;opacity:.75;margin-top:3px}
.inv .mh-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:14.5px;margin-top:10px;line-height:1.3}
.inv .mh-bis{font-family:"Amiri",serif;font-size:15px;color:var(--accent);margin-bottom:8px}
/* the gleam that runs over the gold when the card opens */
.inv .mh-gleam{position:absolute;inset:0;pointer-events:none;opacity:0;mix-blend-mode:soft-light;
  background:linear-gradient(105deg,transparent 38%,rgba(255,244,214,.95) 50%,transparent 62%) 130% 0/260% 100% no-repeat}

/* cover */
.inv .cv-mihrab2{background:var(--ground);overflow:hidden;transition:opacity .45s .95s}
.inv .mh-stage{position:absolute;left:9%;right:9%;top:6.5%;z-index:2;transform:rotate(-.6deg);transform-origin:50% 40%;transition:transform 1.25s cubic-bezier(.45,0,.2,1)}
.inv .mh-foot{position:absolute;left:0;right:0;bottom:6%;z-index:3;display:flex;flex-direction:column;align-items:center;gap:16px;color:var(--pagefg);transition:opacity .35s}
.inv .mh-to{text-align:center}
.inv .mh-to small{display:block;font-family:"Cormorant Garamond",serif;font-size:10px;letter-spacing:.32em;text-transform:uppercase;opacity:.8}
.inv .mh-to b{font-family:"Pinyon Script",cursive;font-weight:400;font-size:27px;line-height:1.3}
.inv .mh-open{cursor:pointer;padding:13px 38px;border-radius:999px;border:1px solid color-mix(in srgb,var(--gold) 85%,transparent);background:color-mix(in srgb,var(--ground) 70%,transparent);color:var(--pagefg);
  font-family:"Cormorant Garamond",serif;font-size:12.5px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;box-shadow:inset 0 0 0 3px color-mix(in srgb,var(--ground) 80%,transparent),inset 0 0 0 4px color-mix(in srgb,var(--gold) 40%,transparent)}
/* opening: the gold catches the light once and the leaf settles into place */
.inv.opening .mh-foot{opacity:0}
.inv.opening .mh-stage{transform:rotate(0) translateY(2%) scale(1.06)}
.inv.opening .mh-stage .mh-gleam{animation:mhGleam 1.1s ease-in-out .1s both}
@keyframes mhGleam{0%{opacity:0;background-position:130% 0}25%{opacity:1}80%{opacity:1}100%{opacity:0;background-position:-30% 0}}
.inv.opening .cv-mihrab2{opacity:0}

/* page */
.inv .pg-mihrab2{background:var(--ground);color:var(--pagefg);padding:30px 18px 96px;gap:18px;overflow:hidden}
.inv .pg-mihrab2 > :not(.mh-leath){position:relative;z-index:2}
.inv .pg-mihrab2 .mh-leaf{max-width:350px}
.inv .mh-leaf.big .mh-txt{left:17%;right:17%;top:22%;bottom:6%}
.inv .mh-leaf.big .mh-k{font-size:9.5px}
.inv .mh-leaf.big .mh-names{font-size:clamp(34px,11cqi,44px);margin:12px 0}
.inv .mh-leaf.big .mh-date{font-size:10.5px;letter-spacing:.2em}
.inv .mh-tabs{display:flex;gap:10px;justify-content:center}
.inv .mh-pill{padding:11px 24px;border-radius:999px;border:1px solid color-mix(in srgb,var(--gold) 80%,transparent);color:var(--pagefg);text-decoration:none;
  font-family:"Cormorant Garamond",serif;font-weight:600;font-size:11.5px;letter-spacing:.24em;text-transform:uppercase;background:color-mix(in srgb,var(--ground) 60%,transparent)}

/* skin: vellum leaves ruled in gold, blue and black, a gilt roundel over each heading */
.fam-mihrab .scroller{background:var(--ground)}
.fam-mihrab .scroller::before{content:"";position:fixed;inset:0;pointer-events:none;background:url(/assets/velvet.jpg) 0 0/180px;mix-blend-mode:soft-light;opacity:.5}
.fam-mihrab.cardsecs .sec{background:var(--sheet) url(/assets/paper.jpg) 0 0/260px;background-blend-mode:multiply;border-radius:1px!important;padding:52px 30px 40px;color:var(--ink);
