.fam-mihrab .seg button[aria-pressed="true"],.fam-mihrab button.submit{background:var(--accent)!important;color:#fbf6ea!important;border-color:var(--accent)!important}
.fam-mihrab .dock{background:color-mix(in srgb,var(--ground) 92%,transparent);color:var(--pagefg);border-top:1px solid color-mix(in srgb,var(--gold) 40%,transparent)}
.fam-mihrab .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .mh-stage{transition:none}.inv.opening .mh-stage .mh-gleam{animation:none}}
.fam-mihrab .dock button{color:var(--pagefg)}
.fam-mihrab .dock svg{color:color-mix(in srgb,var(--gold) 65%,var(--pagefg))}
.fam-mihrab .dock button,.fam-mihrab .dock button span{color:var(--pagefg)!important;opacity:1}

/* ===== monogram ===== */
.inv .cv-monogram{background:transparent;overflow:hidden;transition:opacity .6s .9s}
