.inv .monogram-card{position:absolute;inset:24px 18px 26px;background:var(--sheet);border-radius:2px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;padding:9% 11% 13%;text-align:center;color:var(--ink);
 box-shadow:0 1px 0 color-mix(in srgb,var(--sheet) 88%,#000),0 2px 0 color-mix(in srgb,var(--sheet) 82%,#000),0 3px 0 color-mix(in srgb,var(--sheet) 76%,#000),0 4px 1px color-mix(in srgb,var(--sheet) 70%,#000),0 18px 34px rgba(0,0,0,.38);
 transition:transform 1s .5s cubic-bezier(.4,0,.2,1),opacity .7s .8s,box-shadow 1s .5s}
