.inv .monogram-hint{position:absolute!important;left:0;right:0;bottom:12%;font-family:"Cormorant Garamond",serif;font-size:9.5px;letter-spacing:.3em;text-transform:uppercase;opacity:.55;transition:opacity .3s}
.inv.opening .cv-monogram .monogram-emb .lo{transform:translate(2.3px,2.7px)}
.inv.opening .cv-monogram .monogram-emb .hi{transform:translate(-1.8px,-1.8px)}
