.inv.opening .monogram-hint{opacity:0}
.inv.opening .cv-monogram .monogram-card{transform:translateY(-5%) scale(1.035);opacity:0;box-shadow:0 1px 0 color-mix(in srgb,var(--sheet) 88%,#000),0 40px 60px rgba(0,0,0,.3)}
.inv.opening .cv-monogram{opacity:0}
/* page: deep-impression letterpress */
.inv .pg-monogram{padding:20px 16px 72px;align-items:stretch}
.inv .pg-monogram .monogram-card{position:relative;inset:auto;flex:1;padding:12% 12% 11%;gap:10px;transition:none}
