/* skin: plate-marked cotton cards, blind-embossed badges */
.fam-monogram .scroller{background:radial-gradient(ellipse 90% 70% at 50% 45%,color-mix(in srgb,var(--ground) 86%,#fff),var(--ground) 75%) fixed}
.fam-monogram.cardsecs .sec{background:var(--sheet);border-radius:2px;box-shadow:0 1px 0 color-mix(in srgb,var(--sheet) 86%,#000),0 2px 0 color-mix(in srgb,var(--sheet) 78%,#000),0 3px 1px color-mix(in srgb,var(--sheet) 72%,#000),0 14px 26px rgba(0,0,0,.28)}
