  background:linear-gradient(180deg,rgba(255,255,255,.7),rgba(255,255,255,.55) 50%,rgba(255,255,255,.66));-webkit-backdrop-filter:blur(2.5px);backdrop-filter:blur(2.5px);
  box-shadow:0 1px 2px rgba(0,0,0,.18),0 -1px 0 rgba(255,255,255,.6),inset 0 4px 0 -3px color-mix(in srgb,var(--gold) 70%,transparent),inset 0 -4px 0 -3px color-mix(in srgb,var(--gold) 70%,transparent);
  transition:transform .6s cubic-bezier(.5,0,.6,1) .05s,opacity .45s .2s}
.inv .ok-band::before,.inv .ok-band::after{content:"";position:absolute;top:0;bottom:0;width:1.2%;background:rgba(0,0,0,.08)}
.inv .ok-band::before{left:0}.inv .ok-band::after{right:0}
.inv .ok-band p{position:absolute;left:0;right:0;top:9%;text-align:center;color:var(--ink)}
.inv .ok-band small{display:block;font-family:"Cormorant Garamond",serif;font-weight:600;font-size:2.5cqi;letter-spacing:.26em;text-transform:uppercase;color:var(--accent)}
.inv .ok-band b{display:block;font-family:"Cormorant Garamond",serif;font-style:italic;font-weight:500;font-size:5.6cqi;line-height:1.15;margin-top:.5cqi}
/* the seal on the band's lower edge is the button */
.inv .ok-open{position:absolute;left:50%;top:calc(50% - 66cqi + 125.3cqi * .83 - 8cqi);transform:translateX(-50%);z-index:5;border:0;background:none;padding:0;cursor:pointer;
  display:flex;flex-direction:column;align-items:center;gap:1.4cqi;transition:opacity .35s,transform .45s}
.inv .ok-seal{display:flex;align-items:center;justify-content:center;width:16cqi;aspect-ratio:1;background:var(--seal) center/contain no-repeat;filter:drop-shadow(0 4px 4px rgba(30,15,10,.4))}
.inv .ok-seal span{display:flex;align-items:baseline;gap:.5px;font-family:"Federo",sans-serif;font-size:5.6cqi;color:rgba(0,0,0,.34);text-shadow:0 1px 0 rgba(255,255,255,.35),0 -1px 0 rgba(0,0,0,.25)}
.inv .ok-seal .ok-jw{font-family:"Amiri",serif;font-weight:400}
.inv .ok-lbl{font-family:"Federo",sans-serif;font-size:2.9cqi;letter-spacing:.3em;text-transform:uppercase;color:var(--oklbl);text-shadow:0 1px 0 rgba(0,0,0,.15);white-space:nowrap}
/* opening: the seal and band slip off, then the doors swing open */
.inv.opening .ok-open{opacity:0;transform:translateX(-50%) translateY(8px)}
.inv.opening .ok-band{transform:translateY(70%);opacity:0}
.inv.opening .ok-door.l{transform:rotateY(-84deg);opacity:0}
.inv.opening .ok-door.r{transform:rotateY(84deg);opacity:0}
.inv.opening .ok-env{opacity:0;transform:rotate(-6deg) translateY(10%)}
.inv.opening .cv-orkid{opacity:0}

/* page: the inside of the gatefold, doors folded back */
.inv .pg-orkid{background:var(--ground);color:var(--ink);padding:18px 0 70px;justify-content:flex-start;min-height:100%}
.inv .pg-orkid > .ok-bg{z-index:0}
.inv .ok-open-wrap{position:static;width:100%;display:flex;justify-content:center;flex:1}
.inv .ok-wing{position:absolute;top:0;bottom:0;width:13cqi;z-index:1;overflow:hidden;
  background:linear-gradient(90deg,rgba(0,0,0,.08),transparent 40%,rgba(255,255,255,.08)),url(/assets/paper.jpg) 0 0/260px,var(--door);background-blend-mode:normal,multiply,normal}
.inv .ok-wing.l{left:0;box-shadow:inset -10px 0 12px -8px rgba(0,0,0,.35)}
.inv .ok-wing.r{right:0;box-shadow:inset 10px 0 12px -8px rgba(0,0,0,.35)}
.inv .ok-wing .ok-foil{inset:auto;top:0;width:80cqi;height:125.3cqi;animation:none;transform:scaleX(-1);filter:drop-shadow(0 .5px .3px rgba(0,0,0,.3))}
.inv .ok-wing.l .ok-foil{right:0}
.inv .ok-wing.r .ok-foil{left:0}
.inv .ok-inside{position:relative;z-index:2;width:76cqi;margin:0 auto;padding:15cqi 7cqi 10cqi;display:flex;flex-direction:column;align-items:center;text-align:center;
  background:radial-gradient(ellipse at 50% 20%,rgba(255,255,255,.55),transparent 60%),url(/assets/paper.jpg) 0 0/220px,var(--sheet);background-blend-mode:normal,multiply,normal;
  box-shadow:-6px 0 10px -6px rgba(0,0,0,.35),6px 0 10px -6px rgba(0,0,0,.35),0 14px 24px -10px rgba(0,0,0,.35)}
.inv .ok-arch{position:absolute;left:4cqi;right:4cqi;top:3cqi;height:40cqi;fill:none;stroke:var(--gold);stroke-width:1.1;pointer-events:none}
.inv .ok-arch .t{stroke-width:.5}
.inv .ok-sprig{position:absolute;left:50%;top:5.4cqi;width:26cqi;height:7.4cqi;transform:translateX(-50%);
  background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--oksprig) center/contain no-repeat;mask:var(--oksprig) center/contain no-repeat}
.inv .ok-foot{display:block;width:26cqi;height:7cqi;margin-top:3.6cqi;transform:scaleY(-1);
  background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--oksprig) center/contain no-repeat;mask:var(--oksprig) center/contain no-repeat}
.inv .ok-bis{font-family:"Amiri",serif;font-size:4.6cqi;color:var(--accent);margin-bottom:3cqi}
.inv .pg-orkid .couple-ph.front{width:31cqi;aspect-ratio:4/5;margin:0 auto 3cqi;border-radius:999px 999px 4px 4px;overflow:hidden;
  box-shadow:0 0 0 1px var(--gold),0 0 0 4px var(--sheet),0 0 0 5px color-mix(in srgb,var(--gold) 60%,transparent),0 10px 18px -8px rgba(0,0,0,.4)}
.inv .pg-orkid .ok-k{font-size:2.9cqi}
.inv .pg-orkid .ok-names{font-size:clamp(32px,10.6cqi,46px);margin:2.6cqi 0 2.4cqi;overflow-wrap:anywhere}
.inv .ok-dblock{display:flex;flex-direction:column;align-items:center;gap:1.2cqi;padding:2.6cqi 0;margin:.6cqi 0 2.4cqi;width:100%;
  border-top:1px solid color-mix(in srgb,var(--gold) 55%,transparent);border-bottom:1px solid color-mix(in srgb,var(--gold) 55%,transparent);
  box-shadow:inset 0 3px 0 -2px color-mix(in srgb,var(--gold) 30%,transparent),inset 0 -3px 0 -2px color-mix(in srgb,var(--gold) 30%,transparent)}
.inv .ok-dblock small{font-family:"Cormorant Garamond",serif;font-weight:600;font-size:3cqi;letter-spacing:.3em;text-transform:uppercase;color:var(--accent)}
.inv .ok-dblock small.hj{font-weight:400;font-style:italic;letter-spacing:.04em;text-transform:none;font-size:3.7cqi;color:var(--ink);opacity:.8}
.inv .ok-num{font-size:7.6cqi;letter-spacing:.02em;line-height:1;color:var(--accent)}
.inv .ok-ven{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:4.6cqi;color:var(--ink)}
.inv .ok-pills{display:flex;gap:2.5cqi;margin-top:4cqi;flex-wrap:wrap;justify-content:center}
.inv .ok-pill{padding:3.2cqi 6cqi;border-radius:999px;background:var(--accent);color:var(--sheet);text-decoration:none;font-family:"Federo",sans-serif;font-size:2.9cqi;letter-spacing:.2em;text-transform:uppercase;box-shadow:inset 0 0 0 1px rgba(255,255,255,.25),0 4px 8px -4px rgba(0,0,0,.4)}
.inv .ok-pill.ghost{background:transparent;color:var(--accent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--gold) 80%,transparent)}

/* skin: cream inner-card panels with a foil arch hairline and foil orchid headings */
.fam-orkid .scroller{background:linear-gradient(90deg,rgba(0,0,0,.06),transparent 12%,transparent 88%,rgba(0,0,0,.06)),var(--ground)}
.fam-orkid .scroller::before{content:"";position:fixed;inset:0;pointer-events:none;background:url(/assets/linen.jpg) 0 0/220px;mix-blend-mode:soft-light;opacity:.45}
.fam-orkid.cardsecs .sec{position:relative;border-radius:46% 46% 3px 3px / 54px 54px 3px 3px;padding-top:58px!important;color:var(--ink);
  background:radial-gradient(ellipse at 50% 0,rgba(255,255,255,.55),transparent 55%),url(/assets/paper.jpg) 0 0/220px,var(--sheet);background-blend-mode:normal,multiply,normal;
  box-shadow:inset 0 0 0 6px var(--sheet),inset 0 0 0 7px color-mix(in srgb,var(--gold) 75%,transparent),inset 0 0 0 9px var(--sheet),inset 0 0 0 9.6px color-mix(in srgb,var(--gold) 40%,transparent),0 16px 26px -12px rgba(0,0,0,.4)}
.fam-orkid .sec h2{font-family:"Federo",sans-serif;font-weight:400;text-transform:uppercase;letter-spacing:.24em;font-size:18px;color:var(--accent)}
.fam-orkid .sec h2::before{content:"";display:block;width:116px;height:33px;margin:0 auto 10px;background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;
  -webkit-mask:var(--oksprig) center/contain no-repeat;mask:var(--oksprig) center/contain no-repeat}
.fam-orkid .sec h2::after{content:"";display:block;width:120px;height:7px;margin:10px auto 0;border:0;
  background:radial-gradient(circle,var(--gold) 2px,transparent 2.5px) center/7px 7px no-repeat,linear-gradient(var(--gold),var(--gold)) 0 50%/44% 1px no-repeat,linear-gradient(var(--gold),var(--gold)) 100% 50%/44% 1px no-repeat}
.fam-orkid .sec,.fam-orkid .sec p,.fam-orkid .info b{color:var(--ink)}
.fam-orkid .info,.fam-orkid .info > div{border:0!important;background:none!important;box-shadow:none!important}
.fam-orkid .info > div{border-bottom:1px solid color-mix(in srgb,var(--gold) 34%,transparent)!important;padding:14px 6px!important}
.fam-orkid .info > div:last-child{border-bottom:0!important}
.fam-orkid .info span{color:var(--accent);letter-spacing:.22em}
.fam-orkid .ibtn{border-radius:999px;color:var(--accent);background:transparent;border-color:color-mix(in srgb,var(--gold) 65%,transparent)}
.fam-orkid .count b{color:var(--accent);font-family:"Federo",sans-serif;font-weight:400}
.fam-orkid input,.fam-orkid select,.fam-orkid textarea{background:rgba(255,255,255,.75)!important;color:var(--ink)!important;border-color:color-mix(in srgb,var(--gold) 55%,transparent)!important}
.fam-orkid .seg button{border-radius:999px!important;color:var(--ink)}
.fam-orkid .seg button[aria-pressed="true"],.fam-orkid button.submit{background:var(--accent)!important;color:var(--sheet)!important;border-color:var(--accent)!important;border-radius:999px}
.fam-orkid .dock{background:color-mix(in srgb,var(--sheet) 94%,transparent);color:var(--accent);backdrop-filter:blur(6px)}
.fam-orkid .foot{color:var(--pagefg)}
@media (prefers-reduced-motion: reduce){.inv .ok-foil{animation:none}.inv .ok-door,.inv .ok-band,.inv .ok-env{transition:opacity .3s}}
.inv .ok-arc{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.inv .ok-arc text{font-family:"Cormorant Garamond",serif;font-weight:700;font-size:8.6px;letter-spacing:.24em;text-transform:uppercase;fill:var(--accent)}
.inv .ok-cast{transition:opacity .4s .45s}.inv.opening .ok-cast{opacity:0}
.inv .cv-orkid .ok-names span{white-space:nowrap}
.inv .pg-orkid .ok-names span{white-space:nowrap}

/* ===== pasport ===== */
.inv .cv-pasport{background:var(--ground);overflow:hidden;transition:opacity .45s 1.05s}
.inv .cv-pasport .pasport-desk,.inv .pg-pasport .pasport-desk{position:absolute;inset:0;background:radial-gradient(ellipse 75% 55% at 50% 42%,color-mix(in srgb,var(--ground) 86%,#fff),var(--ground) 62%,color-mix(in srgb,var(--ground) 82%,#000))}
.inv .cv-pasport .pasport-desk::after,.inv .pg-pasport .pasport-desk::after{content:"";position:absolute;inset:0;background:url(/assets/linen.jpg) 0 0/260px;mix-blend-mode:soft-light;opacity:.5}
.inv .pasport-top{position:absolute;top:6.2%;left:0;right:0;text-align:center;z-index:2;font-family:var(--d);font-size:10px;letter-spacing:.38em;text-transform:uppercase;color:var(--pagefg);opacity:.8;transition:opacity .4s}
.inv .pasport-stage{position:absolute;left:50%;top:11.5%;width:min(76%,300px);aspect-ratio:88/125;transform:translateX(-50%);perspective:1700px;z-index:3}
.inv .pasport-book{position:absolute;inset:0;transform-style:preserve-3d;transition:transform 1.3s cubic-bezier(.55,0,.25,1)}
/* back board and page block, seen as thickness at the fore-edge */
.inv .pasport-book::before{content:"";position:absolute;inset:0;border-radius:4px 11px 11px 4px;background:color-mix(in srgb,var(--accent) 70%,#000);transform:translate(5px,6px);box-shadow:0 22px 34px -8px rgba(0,0,0,.55),0 4px 10px rgba(0,0,0,.3)}
.inv .pasport-book::after{content:"";position:absolute;top:2px;bottom:2px;right:-3px;width:10px;border-radius:0 6px 6px 0;background:repeating-linear-gradient(90deg,color-mix(in srgb,var(--sheet) 92%,#000) 0 1px,var(--sheet) 1px 2px);transform:translate(1px,2px);z-index:-1}
.inv .pasport-inside{position:absolute;inset:0 1px 0 0;border-radius:3px 9px 9px 3px;background:var(--wave) 0 0/60px 20px,var(--sheet);overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;color:var(--ink);box-shadow:inset 14px 0 18px -10px rgba(0,0,0,.35)}
.inv .pasport-inside .pasport-endp{position:absolute;inset:7%;border:1px solid color-mix(in srgb,var(--accent) 35%,transparent);outline:1px solid color-mix(in srgb,var(--accent) 20%,transparent);outline-offset:3px}
.inv .pasport-inhd{font-family:"Jost",sans-serif;font-size:9px;letter-spacing:.3em;text-transform:uppercase;opacity:.7}
.inv .pasport-inn{font-family:var(--s);font-size:clamp(26px,8cqi,32px);color:var(--accent);line-height:1.1}
.inv .pasport-front{position:absolute;inset:0;transform-style:preserve-3d;transform-origin:0 50%;transition:transform 1.3s cubic-bezier(.55,0,.25,1)}
.inv .pasport-tap{position:absolute;inset:0;z-index:6;border:0;padding:0;margin:0;background:none;cursor:pointer;border-radius:4px 11px 11px 4px}
.inv.opening .pasport-tap{pointer-events:none}
.inv .pasport-face{position:absolute;inset:0;border-radius:4px 11px 11px 4px;overflow:hidden;-webkit-backface-visibility:hidden;backface-visibility:hidden}
.inv .pasport-face.out{background:radial-gradient(ellipse 90% 70% at 38% 30%,color-mix(in srgb,var(--accent) 86%,#fff),var(--accent) 55%,color-mix(in srgb,var(--accent) 78%,#000));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 60%,#000),inset 0 1px 0 1.5px rgba(255,255,255,.07)}
.inv .pasport-face.in{transform:rotateY(180deg);background:var(--wave) 0 0/60px 20px,color-mix(in srgb,var(--sheet) 88%,var(--accent))}
.inv .pasport-face.in .pasport-endp{position:absolute;inset:6%;border:1px solid color-mix(in srgb,var(--accent) 40%,transparent)}
.inv .pasport-grain{position:absolute;inset:0;background:url(/assets/velvet.jpg) 0 0/200px;mix-blend-mode:soft-light;opacity:.9}
.inv .pasport-spine{position:absolute;left:0;top:0;bottom:0;width:10%;background:linear-gradient(90deg,rgba(0,0,0,.42),rgba(0,0,0,.12) 55%,rgba(255,255,255,.08) 72%,rgba(0,0,0,.2) 78%,transparent)}
.inv .pasport-blind{position:absolute;inset:4.6% 5% 4.6% 12%;border-radius:4px;border:1px solid rgba(0,0,0,.3);box-shadow:0 1px 0 rgba(255,255,255,.1),inset 0 1px 0 rgba(255,255,255,.08)}
.inv .pasport-emb{position:absolute;left:12%;right:5%;display:block;text-align:center;filter:drop-shadow(0 1px .4px rgba(0,0,0,.55)) drop-shadow(0 -.5px 0 rgba(255,255,255,.18))}
.inv .pasport-names,.inv .pasport-ev,.inv .pasport-word,.inv .pasport-sub{background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.inv .pasport-names{top:9%;font-family:var(--d);font-size:clamp(12px,3.9cqi,15px);letter-spacing:.26em;text-transform:uppercase;line-height:1.3}
.inv .pasport-names i{font-family:"Cormorant Garamond",serif;font-style:italic;text-transform:none;letter-spacing:0;margin:0 .45em;font-size:1.2em}
.inv .pasport-ev{top:16.4%;font-family:"Jost",sans-serif;font-size:8.5px;letter-spacing:.42em;text-transform:uppercase}
.inv .pasport-crestw{top:26%;left:calc(12% + 12%);right:calc(5% + 12%);aspect-ratio:1}
.inv .pasport-crest{position:absolute;inset:0;background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--crest) center/contain no-repeat;mask:var(--crest) center/contain no-repeat}
.inv .pasport-word{top:67%;font-family:var(--d);font-size:clamp(20px,6.4cqi,25px);letter-spacing:.42em;text-transform:uppercase;padding-left:.42em}
.inv .pasport-sub{top:75.5%;font-family:"Jost",sans-serif;font-size:9px;letter-spacing:.4em}
.inv .pasport-chipw{top:84%;left:calc(12% + 36%);right:calc(5% + 36%);aspect-ratio:40/26}
.inv .pasport-chip{position:absolute;inset:0;background:url(/assets/foil.jpg) 0 0/180px,var(--gold);background-blend-mode:overlay;-webkit-mask:var(--chip) center/contain no-repeat;mask:var(--chip) center/contain no-repeat}
.inv .pasport-foot{position:absolute;left:0;right:0;bottom:8.5%;z-index:2;text-align:center;color:var(--pagefg);display:flex;flex-direction:column;gap:12px;align-items:center;transition:opacity .4s}
.inv .pasport-to{font-family:"Cormorant Garamond",serif;font-style:italic;font-size:14px;display:flex;flex-direction:column;gap:2px}
.inv .pasport-to b{font-family:var(--d);font-style:normal;font-weight:400;font-size:13px;letter-spacing:.2em;text-transform:uppercase}
.inv .pasport-hint{font-family:"Jost",sans-serif;font-size:9.5px;letter-spacing:.3em;text-transform:uppercase;opacity:.6;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--pagefg) 30%,transparent)}
.inv.opening .pasport-front{transform:rotateY(-162deg)}
.inv.opening .pasport-book{transform:translateX(14%)}
.inv.opening .pasport-top,.inv.opening .pasport-foot{opacity:0}
.inv.opening .cv-pasport{opacity:0}
/* page: the open booklet, visa page above the data page */
.inv .pg-pasport{background:var(--ground);padding:28px 12px 34px;gap:12px;justify-content:center}
.inv .pg-pasport > :not(.pasport-desk){position:relative;z-index:2}
.inv .pg-pasport > .kicker{color:var(--pagefg);opacity:.85}
.inv .pasport-open{position:relative;width:100%;max-width:372px;padding:7px;border-radius:12px;background:radial-gradient(ellipse at 40% 30%,color-mix(in srgb,var(--accent) 88%,#fff),var(--accent) 60%,color-mix(in srgb,var(--accent) 75%,#000));box-shadow:0 24px 36px -12px rgba(0,0,0,.55),0 3px 8px rgba(0,0,0,.25);display:flex;flex-direction:column;isolation:isolate}
.inv .pasport-open::before{content:"";position:absolute;inset:0;border-radius:12px;background:url(/assets/velvet.jpg) 0 0/200px;mix-blend-mode:soft-light;opacity:.9;z-index:-1}
.inv .pasport-pg{position:relative;aspect-ratio:125/86;overflow:hidden;color:var(--ink);text-align:left;background:var(--wave) 0 0/60px 20px,var(--sheet)}
.inv .pasport-pg::after{content:"";position:absolute;inset:0;background:url(/assets/paper.jpg) 0 0/280px;mix-blend-mode:multiply;opacity:.5;pointer-events:none}
.inv .pasport-pg.visa{border-radius:5px 5px 1px 1px;background:var(--wave2) 0 0/50px 18px,color-mix(in srgb,var(--sheet) 94%,var(--gold));box-shadow:inset 0 -22px 20px -16px rgba(0,0,0,.28)}
.inv .pasport-pg.data{border-radius:1px 1px 5px 5px;box-shadow:inset 0 22px 20px -16px rgba(0,0,0,.28)}
.inv .pasport-fold{position:relative;height:1px;background:color-mix(in srgb,var(--accent) 40%,#000);z-index:3}
.inv .pasport-fold::before{content:"";position:absolute;left:12%;right:12%;top:-1px;border-top:1.4px dashed color-mix(in srgb,var(--gold) 80%,#fff);opacity:.8}
.inv .pasport-pghd{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:baseline;padding:8px 12px 0;font-family:"Jost",sans-serif;font-size:7.5px;letter-spacing:.2em;text-transform:uppercase;color:color-mix(in srgb,var(--ink) 70%,transparent)}
.inv .pasport-pghd i{font-style:normal;opacity:.7}
.inv .pasport-pghd b{font-family:"IBM Plex Mono",monospace;font-weight:600;letter-spacing:.08em;color:var(--ink);font-size:9px}
.inv .pasport-stamps{position:absolute;inset:0}
.inv .pasport-st{position:absolute;display:block;height:auto;mix-blend-mode:multiply;opacity:.9}
.inv .pasport-st.round{left:5%;top:15%;width:34%;transform:rotate(-11deg)}
.inv .pasport-st.rect{right:6%;top:21%;width:50%;transform:rotate(3.5deg)}
.inv .pasport-st.hex{left:41%;bottom:5%;width:26%;transform:rotate(-4deg)}
.inv .pasport-perf{position:absolute;right:4px;top:18%;writing-mode:vertical-rl;font-family:"IBM Plex Mono",monospace;font-size:8.5px;letter-spacing:.32em;color:color-mix(in srgb,var(--ink) 28%,transparent);margin:0;z-index:2}
.inv .pasport-dbody{position:relative;z-index:2;display:grid;grid-template-columns:29% 1fr;gap:10px;padding:7px 12px 0}
