/* ===== tingkap (round 7) ===== */
.inv .tgk-wall{position:absolute;inset:0;background:radial-gradient(ellipse 85% 60% at 30% 18%,rgba(255,250,235,.32),transparent 65%),radial-gradient(ellipse at 50% 50%,transparent 50%,rgba(40,28,18,.2)),
  var(--lime) 0 0/420px,var(--plas) 0 0/160px,url(/assets/paper.jpg) 0 0/340px,var(--ground);background-blend-mode:normal,normal,normal,soft-light,multiply,normal}
.inv .tgk-k{font-family:"Cormorant Garamond",serif;font-size:10.5px;font-weight:500;letter-spacing:.36em;text-transform:uppercase}
/* timber: paint over bare wood, worn through in chips, darker in the corners */
.inv .tgk-win,.inv .tgk-tran,.inv .tgk-sill,.inv .tgk-shut,.inv .tgk-raise,.inv .tgk-fan,.inv .tgk-pc,.inv .tgk-field{
  background:var(--gv) 0 0/240px 600px,var(--mot) 0 0/320px,var(--chip) 0 0/260px,linear-gradient(90deg,rgba(255,255,255,.06),rgba(0,0,0,.08)),var(--wood)}
.inv .tgk-tran,.inv .tgk-sill,.inv .tgk-fan{background:var(--gh) 0 0/600px 240px,var(--mot) 40px 0/320px,var(--chip) 90px 30px/260px,linear-gradient(180deg,rgba(255,255,255,.08),rgba(0,0,0,.12)),var(--wood)}
.inv .tgk-shut.r{background-position:120px 0,160px 90px,130px 70px,0 0,0 0}
.inv .tgk-raise{background-position:30px 200px,60px 60px,50px 150px,0 0,0 0}
/* worn edges: a ring of dense chips round each piece */
.inv .tgk-wear{position:absolute;inset:0;display:block;pointer-events:none;padding:2.5px;background:var(--edge) 0 0/200px;
  -webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0);opacity:.9}
.inv .tgk-win > .tgk-wear{padding:4px;background-position:70px 30px}
.inv .tgk-win{position:relative;display:block;width:100%;padding:4.6%;border-radius:1.5px 2px 1px 2px;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.35),inset 2px 2px 1px rgba(255,248,230,.12),inset -2px -3px 2px rgba(0,0,0,.3),inset 0 0 18px rgba(30,20,10,.3),
    0 26px 28px -16px rgba(30,20,12,.55),6px 10px 18px -6px rgba(30,20,12,.3),0 2px 3px rgba(30,20,12,.3)}
/* the dark interior gap between frame and shutters */
.inv .tgk-arch{position:relative;display:block;background:#140e09;box-shadow:inset 0 0 0 1px rgba(0,0,0,.6),inset 3px 4px 6px rgba(0,0,0,.8)}
.inv .tgk-fanw{position:relative;display:block;aspect-ratio:300/84;overflow:hidden}
/* daylight seen through the piercings: the view outside, blurred and overexposed, with a soft bloom */
.inv .tgk-sky{position:absolute;inset:-8px;display:block;background:var(--view) var(--vpos)/cover;filter:var(--skyf)}
.inv .tgk-sky::after{content:"";position:absolute;inset:0;opacity:var(--bloom);background:radial-gradient(ellipse 60% 80% at 50% 30%,rgba(255,250,232,.75),rgba(255,244,214,.25) 60%,transparent)}
.inv .tgk-fan{position:absolute;inset:0;-webkit-mask:var(--fan) center/100% 100% no-repeat;mask:var(--fan) center/100% 100% no-repeat}
.inv .tgk-fanw > .tgk-fan,.inv .tgk-pw > .tgk-pc{filter:drop-shadow(1.2px 1.8px .6px rgba(0,0,0,.7)) drop-shadow(-.5px -.5px 0 rgba(255,240,205,.35))}
.inv .tgk-fanw::after,.inv .tgk-pw::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.45),inset 3px 4px 6px rgba(0,0,0,.5)}
.inv .tgk-tran{position:relative;display:block;height:12px;box-shadow:0 4px 5px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,248,230,.18),inset 0 -1px 0 rgba(0,0,0,.3)}
.inv .tgk-open{position:relative;display:block;aspect-ratio:.84;perspective:900px;overflow:hidden}
.inv .tgk-view{position:absolute;inset:0;background:var(--view) var(--vpos)/cover;transition:transform 1.4s cubic-bezier(.3,.1,.2,1)}
.inv .tgk-view::after{content:"";position:absolute;inset:0;box-shadow:inset 0 0 22px rgba(0,0,0,.55);background:linear-gradient(180deg,rgba(255,240,210,.12),transparent 50%)}
/* two leaves, not quite even: one hangs a hair low and its paint is a touch more faded */
.inv .tgk-shut{position:absolute;top:0;bottom:0;width:50%;display:block;transition:transform 1.25s cubic-bezier(.45,.05,.2,1);
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.5),inset 2px 2px 1px rgba(255,248,230,.13),inset -2px -2px 2px rgba(0,0,0,.28),inset 0 -30px 30px -20px rgba(25,15,8,.35)}
.inv .tgk-shut.l{left:0;width:calc(50% - .5px);transform-origin:0 50%}
.inv .tgk-shut.r{right:0;width:calc(50% - 1px);transform-origin:100% 50%;filter:brightness(1.04) saturate(.9)}
.inv .cv-tingkap2 .tgk-shut.r{top:1.5px;bottom:-1px}
/* pierced vent panel at the top of each leaf, light coming through */
.inv .tgk-pw{position:absolute;left:15%;right:15%;top:6%;height:27%;display:block;overflow:hidden;background:#140e09}
.inv .tgk-pc{position:absolute;inset:0;display:block;-webkit-mask:var(--pan) center/100% 100% no-repeat;mask:var(--pan) center/100% 100% no-repeat}
/* recessed panel: a deep shadowed groove, then a raised field with a bevel catching the light from top-left */
.inv .tgk-raise{position:absolute;left:14%;right:14%;top:39%;bottom:7%;display:block;padding:7%;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.55),inset 4px 5px 6px rgba(0,0,0,.6),inset -1px -1px 0 rgba(255,248,230,.16)}
.inv .tgk-field{position:relative;display:block;width:100%;height:100%;box-sizing:border-box;
  border:5px solid;border-color:rgba(255,248,230,.16) rgba(0,0,0,.22) rgba(0,0,0,.32) rgba(255,248,230,.1);background-clip:border-box;
  box-shadow:0 0 0 1px rgba(0,0,0,.35),2px 3px 5px rgba(0,0,0,.4),inset 0 0 0 1px rgba(0,0,0,.18)}
.inv .tgk-field::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 80% 40% at 50% 100%,rgba(30,18,8,.25),transparent 70%)}
.inv .tgk-knob{position:absolute;top:53%;width:9px;height:9px;border-radius:50%;display:block;background:radial-gradient(circle at 35% 30%,#f4e3b0,#a88445 42%,#4e3414 88%);
  box-shadow:1px 2px 2px rgba(0,0,0,.55),0 0 0 3px rgba(40,26,12,.16)}
.inv .tgk-shut.l .tgk-knob{right:6px}.inv .tgk-shut.r .tgk-knob{left:6px;top:53.4%}
.inv .tgk-shut.l::after{content:"";position:absolute;right:-1px;top:0;bottom:0;width:1.5px;background:linear-gradient(rgba(255,240,200,.0),rgba(255,240,200,.45) 30%,rgba(255,240,200,.5) 70%,rgba(255,240,200,0))}
.inv .tgk-sill{position:absolute;left:-6%;right:-6%;bottom:-11px;height:14px;display:block;border-radius:1px 1px 2px 2px;
  box-shadow:inset 0 2px 0 rgba(255,248,230,.22),inset 0 -3px 2px rgba(0,0,0,.3),0 3px 2px rgba(0,0,0,.35),0 18px 16px -8px rgba(30,20,12,.5)}
/* rain has washed a soft stain down the wall under the sill */
.inv .tgk-sill::after{content:"";position:absolute;left:8%;right:8%;top:100%;height:70px;pointer-events:none;
  background:linear-gradient(rgba(60,40,20,.16),transparent),var(--lime) 0 0/200px;-webkit-mask:linear-gradient(#000,transparent);mask:linear-gradient(#000,transparent);opacity:.75}
.inv .pg-tingkap2 .tgk-sill::after{display:none}

