  background:linear-gradient(to top right,transparent 49.6%,rgba(0,0,0,.14) 50%,transparent 58%),linear-gradient(to top left,transparent 49.6%,rgba(255,255,255,.12) 50%,transparent 58%),
  linear-gradient(180deg,rgba(255,255,255,.08),rgba(0,0,0,.1)),url(/assets/linen.jpg) 0 0/180px,var(--env);background-blend-mode:normal,normal,normal,soft-light,normal}
