/* ===== additions for the Next.js app ===== */
body{margin:0;min-height:100vh}
.auth-card{max-width:420px;margin:48px auto 80px}
.auth-card form{display:flex;flex-direction:column;gap:14px}
input[type=email],input[type=password]{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:2px;background:var(--surface)}
input[type=email]:focus,input[type=password]:focus{outline:1px solid var(--fg);border-color:var(--fg)}
.nav form{display:inline}
.nav .linklike{border:0;background:none;padding:8px 10px;font-size:13px;letter-spacing:.06em;color:var(--muted);cursor:pointer}
.nav .linklike:hover{color:var(--fg)}
.inv-page{position:fixed;inset:0;z-index:5;background:#141110;display:flex;justify-content:center}
.inv-page .inv-host{width:100%;max-width:480px;height:100%;position:relative}
.status-note{font-size:13px;color:var(--muted)}
.mock-gw{max-width:440px;margin:48px auto 80px}
.mock-gw .brandbar{display:flex;justify-content:space-between;align-items:center;padding-bottom:12px;border-bottom:1px solid var(--line)}
.fam .slot,.dcard .slot{position:relative}
.dots{flex-wrap:wrap;row-gap:6px} /* families now carry up to ~20 colourways; unwrapped they overflow phones */
.personalise{margin-top:22px;max-width:520px;display:flex;flex-direction:column;gap:6px}
.personalise label{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.personalise .row-line{grid-template-columns:1fr auto}
.personalise input{width:100%}
.order-item .pay-now{margin-left:auto;flex:0 0 auto}
.order-item .t .unpaid{color:var(--danger)}
.ev-card{border:1px solid var(--line);border-radius:4px;padding:12px;display:flex;flex-direction:column;gap:10px}
.ev-card .fieldset{margin:0}
.ev-card .top{display:flex;justify-content:space-between;align-items:center;gap:8px}
.og-prev{width:100%;max-width:360px;aspect-ratio:1.91/1;border:1px solid var(--line);border-radius:4px;overflow:hidden;position:relative;background:var(--surface)}
.og-prev img{width:100%;height:100%;object-fit:cover;display:block}
.og-prev button{position:absolute;top:6px;right:6px}
.members{display:flex;flex-direction:column;gap:8px;margin-top:12px}
.shared-note{font-size:13px;margin-bottom:16px}
.order-row{display:flex;gap:6px;align-items:center}
.order-row .order-item{flex:1;min-width:0}

/* password field with a show/hide toggle */
.pw-wrap{position:relative;display:block}
.pw-wrap input{width:100%;padding-right:64px}
.pw-eye{position:absolute;right:6px;top:50%;transform:translateY(-50%);border:0;background:transparent;font:inherit;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:6px 8px;cursor:pointer}
.pw-eye:hover{color:var(--fg)}

/* design picker: real miniature cards instead of colour swatches */
.tpl-pick{grid-template-columns:repeat(4,minmax(0,1fr))}
.tpl-pick .mini{position:relative;pointer-events:none}
.tpl-pick button{transition:transform .15s,box-shadow .15s}
.tpl-pick button:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(30,18,10,.18)}
@media (max-width:560px){.tpl-pick{grid-template-columns:repeat(3,minmax(0,1fr))}}

/* design picker v2: one tile per design, colours open underneath */
.fam-pick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;grid-auto-flow:row dense}
.fam-tile{border:1px solid var(--line);background:var(--surface);padding:0 0 10px;cursor:pointer;text-align:left;border-radius:2px;overflow:hidden;display:flex;flex-direction:column;transition:transform .15s,box-shadow .15s}
.fam-tile:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(30,18,10,.18)}
.fam-tile[aria-pressed="true"]{outline:2px solid var(--fg);outline-offset:2px}
.fam-tile .mini,.fc-opt .mini{position:relative;pointer-events:none}
.ft-name{font-family:var(--f-display);font-size:19px;font-style:italic;padding:8px 10px 0}
.ft-mean{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding:2px 10px 0}
.fam-colours{grid-column:1/-1;border:1px solid var(--line);background:var(--sunk);padding:14px;display:flex;flex-direction:column;gap:12px}
.fc-head{display:flex;gap:12px;align-items:baseline;flex-wrap:wrap}
.fc-head b{font-family:var(--f-display);font-size:22px;font-style:italic;font-weight:400}
.fc-head span{font-size:13px;color:var(--muted)}
.fc-row{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
.fc-opt{border:1px solid var(--line);background:var(--surface);padding:0 0 6px;cursor:pointer;border-radius:2px;overflow:hidden;display:flex;flex-direction:column;font-size:12px;text-align:left}
.fc-opt span{padding:5px 7px 0}
.fc-opt[aria-pressed="true"]{outline:2px solid var(--fg);outline-offset:2px}
@media (max-width:900px){.fam-pick{grid-template-columns:repeat(3,minmax(0,1fr))}.fc-row{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media (max-width:560px){.fam-pick{grid-template-columns:repeat(2,minmax(0,1fr))}.fc-row{grid-template-columns:repeat(3,minmax(0,1fr))}}

/* no visible scrollbars inside the phone preview or on the step tabs (still scrollable) */
.inv .scroller,.phone .screen,.phone .screen *,.tabs,#ed-tabs,.ed-tabs{scrollbar-width:none;-ms-overflow-style:none}
.inv .scroller::-webkit-scrollbar,.phone .screen::-webkit-scrollbar,.phone .screen *::-webkit-scrollbar,.tabs::-webkit-scrollbar,#ed-tabs::-webkit-scrollbar,.ed-tabs::-webkit-scrollbar{display:none;width:0;height:0}

/* design step: the grid scrolls inside its own box; extra options fold away; Back/Next stay on screen */
.fam-scroll{max-height:min(66vh,720px);overflow-y:auto;padding:4px 6px 14px 4px;margin:0 -6px 18px -4px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);scrollbar-width:thin;overscroll-behavior:contain}
.fam-scroll .fam-pick{padding-top:10px}
.fam-pick{grid-template-columns:repeat(5,minmax(0,1fr))}
@media (max-width:1200px){.fam-pick{grid-template-columns:repeat(4,minmax(0,1fr))}}
details.more-opts{border-bottom:1px solid var(--line);margin-bottom:8px}
details.more-opts>summary{cursor:pointer;list-style:none;padding:14px 0;font-family:var(--f-display);font-size:20px;display:flex;flex-direction:column;gap:2px}
details.more-opts>summary::-webkit-details-marker{display:none}
details.more-opts>summary::before{content:"+ ";font-family:var(--f-body);font-size:16px}
details.more-opts[open]>summary::before{content:"2  "}
details.more-opts>summary .muted{font-family:var(--f-body);font-size:12px}
.foot-nav{position:sticky;bottom:0;z-index:20;background:none;padding:12px 0;margin-top:8px;pointer-events:none}
.foot-nav > *{pointer-events:auto}
.foot-nav .btn{box-shadow:0 8px 22px -6px rgba(40,25,20,.35)}

.jawi-kb .jawi-digits{grid-column:1/-1;display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:4px;padding-bottom:6px;margin-bottom:2px;border-bottom:1px dashed var(--line)}

/* tradition / monogram chips and the Content step */
.chips{display:flex;gap:8px;flex-wrap:wrap}
.sec-row{display:grid;grid-template-columns:22px minmax(0,1fr);gap:10px;align-items:center}
.sec-row input[type=checkbox]{width:18px;height:18px;accent-color:var(--fg)}
.sec-row:has(input[type=checkbox]:not(:checked)) input[type=text]{opacity:.45;text-decoration:line-through}
.csec{display:flex;flex-direction:column;gap:6px;padding:10px;border:1px solid var(--line);background:var(--surface)}

/* home: a taste of the collection, then a link to all of it */
.fam-more{grid-column:1/-1;display:flex;flex-direction:column;align-items:center;gap:10px;padding:18px 0 4px;text-align:center}
.fam-more .muted{font-size:13px}

.faq-contact{margin-top:18px;font-size:14px;color:var(--muted)}.faq-contact a{color:var(--accent);font-weight:500;white-space:nowrap}

/* phones: header stays on one row; all six editor steps visible */
.site-head .btn-sm{white-space:nowrap}
.site-head .btn .xs-hide{display:inline}
@media (max-width:720px){.site-head .wrap{gap:6px}.tabs{flex-wrap:wrap;overflow:visible;gap:0}.tabs button{flex:1 1 33%;padding:10px 6px;font-size:13px;text-align:center}.tabs button .ix{margin-right:4px;font-size:15px}}
@media (max-width:400px){.site-head .btn .xs-hide{display:none}.brand .wm{font-size:22px}}

.foot-nav .mob-only{display:none}
@media (max-width:940px){.foot-nav .mob-only{display:inline-flex}.foot-nav{gap:8px}.foot-nav .btn{padding-inline:18px}}

/* owner admin page */
.admin-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.admin-stats div{border:1px solid var(--line);background:var(--surface);padding:16px 18px}
.admin-stats span{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.admin-stats b{display:block;margin-top:6px;font-family:var(--f-display);font-size:30px;font-weight:500}
.admin-tools{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:0 0 14px}
.admin-tools input{flex:1 1 280px;max-width:460px;padding:11px 14px;border:1px solid var(--line);background:var(--surface);font:inherit}
@media (max-width:720px){.admin-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
